        /**
         * Checks whether the current time falls strictly within active IDX trading market hours.
         * Returns false on Saturdays, Sundays, and outside trading sessions.
         * Used to guard background pollers and prevent API quota leaks.
         */
        function isMarketHoursWIB(): boolean {
            const now = new Date();
            // WIB is UTC+7
            const nowUtcMs = now.getTime() + (now.getTimezoneOffset() * 60000);
            const wibDate = new Date(nowUtcMs + (7 * 3600 * 1000));
            const day = wibDate.getDay(); // 0 = Sunday, 1 = Monday, ..., 5 = Friday, 6 = Saturday
            if (day === 0 || day === 6) return false;

            const hours = wibDate.getHours();
            const minutes = wibDate.getMinutes();
            const minutesOfDay = hours * 60 + minutes;

            // Session 1: 08:55 - 12:05 (Friday 08:55 - 11:35)
            // Session 2: 13:25 - 16:15 (Friday 13:55 - 16:15)
            const isFriday = day === 5;
            const session1Start = 8 * 60 + 55;
            const session1End = isFriday ? (11 * 60 + 35) : (12 * 60 + 5);
            const session2Start = isFriday ? (13 * 60 + 55) : (13 * 60 + 25);
            const session2End = 16 * 60 + 15;

            const inSession1 = minutesOfDay >= session1Start && minutesOfDay <= session1End;
            const inSession2 = minutesOfDay >= session2Start && minutesOfDay <= session2End;

            return inSession1 || inSession2;
        }

