        function canonicalizeForexSymbol(sym: string): string {
            const s = (sym || '').trim();
            if (!s) return '';
            const upper = s.toUpperCase();
            const base = upper.replace(/[MC]$/i, '');
            if (base === 'XAUUSD') return 'XAUUSDm';
            if (base === 'BTCUSD') return 'BTCUSDM';
            if (base === 'XAGUSD') return 'XAGUSDM';
            return base + 'M';
        }

        function cleanForexWatchlist(list: string[]): string[] {
            const seen = new Set<string>();
            const res: string[] = [];
            for (const raw of (list || [])) {
                if (!raw) continue;
                const canon = canonicalizeForexSymbol(raw);
                const baseKey = canon.toUpperCase().replace(/[MC]$/i, '');
                if (!seen.has(baseKey)) {
                    seen.add(baseKey);
                    res.push(canon);
                }
            }
            return res;
        }

