        userWatchlists.forex = cleanForexWatchlist(userWatchlists.forex || defaultForexTradedSymbols);

        // Cache for Total Realized PnL per symbol (sum of realized amounts across all trades)
        const tradedPnlMap = new Map<string, number>();

