        async function loadIdxCatalogs(): Promise<void> {
            try {
                const [stocksRes, brokersRes] = await Promise.all([
                    fetch('/idx_stocks.json').catch(() => null),
                    fetch('/idx_brokers.json').catch(() => null)
                ]);
                if (stocksRes && stocksRes.ok) {
                    const data = await stocksRes.json();
                    if (data.ticker_to_name) {
                        for (const [k, v] of Object.entries(data.ticker_to_name)) {
                            stockNameMap.set(k.toUpperCase().trim(), v as string);
                        }
                    } else if (Array.isArray(data.stocks)) {
                        for (const s of data.stocks) {
                            if (s.ticker && s.name) stockNameMap.set(s.ticker.toUpperCase().trim(), s.name);
                        }
                    }
                    console.log(`[Catalogs] Loaded ${stockNameMap.size} stock names from /idx_stocks.json`);
                }
                if (brokersRes && brokersRes.ok) {
                    const bData = await brokersRes.json();
                    if (bData.code_to_name) {
                        for (const [k, v] of Object.entries(bData.code_to_name)) {
                            brokerNameMap.set(k.toUpperCase().trim(), v as string);
                        }
                    } else if (Array.isArray(bData.brokers)) {
                        for (const b of bData.brokers) {
                            if (b.code && b.name) brokerNameMap.set(b.code.toUpperCase().trim(), b.name);
                        }
                    }
                    console.log(`[Catalogs] Loaded ${brokerNameMap.size} broker names from /idx_brokers.json`);
                }
            } catch (err) {
                console.warn("[Catalogs] Failed to load catalog JSONs:", err);
            }
        }
