                if (runningTradesTableWrap) runningTradesTableWrap.style.display = 'block';
                if (alertsTableWrap) alertsTableWrap.style.display = 'none';
                if (financialsTableWrap) financialsTableWrap.style.display = 'none';
                if (bsTableWrap) bsTableWrap.style.display = 'none';
                updateRtActiveSymbolLabel();
