                if (screenerTabsContainer) screenerTabsContainer.style.display = 'none';
                if (runningTradesControls) runningTradesControls.style.display = 'none';
                if (alertsControls) alertsControls.style.display = 'none';
                if (financialsControls) financialsControls.style.display = 'none';
                if (bsControls) bsControls.style.display = 'none';
