        function toggleSidebarExpand() {
            sidebar?.classList.toggle('expanded');
            const isExp = sidebar?.classList.contains('expanded');
            updateExpandButtons(!!isExp);
        }

        function closeDrawer() {
            sidebar.style.display = 'none';
            sidebar?.classList.remove('expanded');
            updateExpandButtons(false);
            const defaultSidebarHeader = document.getElementById('sidebar-header') as HTMLElement;
            if (defaultSidebarHeader) defaultSidebarHeader.style.display = 'flex';
            dockWatchlistBtn?.classList.remove('active');
            dockScreenerBtn?.classList.remove('active');
            dockRunningTradesBtn?.classList.remove('active');
            dockAlertsBtn?.classList.remove('active');
            dockFinancialsBtn?.classList.remove('active');
            dockBrokerSummaryBtn?.classList.remove('active');
            dockAiSummaryBtn?.classList.remove('active');
            dockHistoryBtn?.classList.remove('active');
            dockCalendarBtn?.classList.remove('active');
            if (historyControls) historyControls.style.display = 'none';
            if (historyTableWrap) historyTableWrap.style.display = 'none';
            if (historyCashflowWrap) historyCashflowWrap.style.display = 'none';
            if (historyMetaStrip) historyMetaStrip.style.display = 'none';
            if (calendarControls) calendarControls.style.display = 'none';
            if (calendarTableWrap) calendarTableWrap.style.display = 'none';
        }

        dockWatchlistBtn?.addEventListener('click', () => openDrawer('watchlist'));
