            'pendapatan': 'Pendapatan (Revenue)',
            'pendapatan_usaha': 'Pendapatan Usaha',
            'beban_pokok_pendapatan': 'Beban Pokok Pendapatan',
            'laba_kotor': 'Laba Kotor (Gross Profit)',
            'beban_usaha': 'Beban Usaha',
            'laba_usaha': 'Laba Usaha (Operating Profit)',
            'pendapatan_beban_lainnya': 'Pendapatan (Beban) Lain',
            'laba_sebelum_pajak': 'Laba Sebelum Pajak (EBT)',
            'beban_pajak': 'Beban Pajak',
            'total_aset': 'Total Aset',
            'aset_lancar': 'Aset Lancar',
            'aset_tidak_lancar': 'Aset Tidak Lancar',
            'total_liabilitas': 'Total Liabilitas',
            'liabilitas_jangka_pendek': 'Liabilitas Jangka Pendek',
