        async function fetchMarketCapData(page = 1, perPage = 50, forceRefresh = false): Promise<MarketCapResponse | null> {
            if (!forceRefresh && mktCapCache.has(page)) {
                return mktCapCache.get(page)!;
            }

            if (!forceRefresh) {
                if (stockMarketCapMap.size === 0) {
                    await loadMarketCapData();
                }
                if (stockMarketCapMap.size >= 50) {
                    const allItems = Array.from(stockMarketCapMap.values());
                    const total = allItems.length;
                    const totalPages = Math.ceil(total / perPage);
                    const startIdx = (page - 1) * perPage;
                    const pageData = allItems.slice(startIdx, startIdx + perPage);
                    if (pageData.length > 0) {
                        const mockResp: MarketCapResponse = {
                            date: new Date().toISOString().split('T')[0],
                            total,
                            page,
                            per_page: perPage,
                            total_pages: totalPages,
                            data: pageData
                        };
                        mktCapCache.set(page, mockResp);
                        return mockResp;
                    }
                }
            }

            const res = await fetchArjumApi(`/api/market-cap?page=${page}&per_page=${perPage}`);
            if (!res || !res.ok) {
                throw new Error(`Gagal mengambil data market cap (${res ? res.status : 'Network error'})`);
            }

            const json: MarketCapResponse = await res.json();
            mktCapCache.set(page, json);
            if (json.data && Array.isArray(json.data)) {
                json.data.forEach(item => {
                    if (item && item.code) {
                        stockMarketCapMap.set(item.code.toUpperCase(), item);
                    }
                });
            }
            return json;
        }

