        async function renderMarketCapTable(page = currentMktCapPage) {
            currentMktCapPage = page;
            const screenerHeaderRow = document.getElementById('screener-header-row');
            const mktCapPagination = document.getElementById('mktcap-pagination');
            const screenerColgroup = document.getElementById('screener-colgroup');
            const mktCapPageNum = document.getElementById('mktcap-page-num');
            const mktCapPageTotal = document.getElementById('mktcap-page-total');
            const mktCapItemTotal = document.getElementById('mktcap-item-total');
            const prevBtn = document.getElementById('mktcap-prev-btn') as HTMLButtonElement | null;
            const nextBtn = document.getElementById('mktcap-next-btn') as HTMLButtonElement | null;

            if (screenerColgroup) {
                screenerColgroup.innerHTML = `
                    <col style="width: 16%;">
                    <col style="width: 32%;">
                    <col style="width: 20%;">
                    <col style="width: 18%;">
                    <col style="width: 14%;">
                `;
            }
            if (screenerHeaderRow) {
                screenerHeaderRow.innerHTML = `
                    <th style="width: 55px; text-align: left;">Sym</th>
                    <th style="text-align: left;">Nama & Harga</th>
                    <th style="text-align: right;">Market Cap</th>
                    <th style="text-align: right;">Total Lot</th>
                    <th style="text-align: right;">Turnover</th>
                `;
            }
            if (mktCapPagination) {
                mktCapPagination.style.display = 'flex';
            }

            screenerTbody.innerHTML = `
                <tr>
                    <td colspan="5" style="text-align: center; color: #787b86; padding: 28px 12px; font-size: 12px;">
                        <div style="font-size: 18px; margin-bottom: 6px;">⏳</div>
                        <div>Memuat data Market Cap halaman ${page}...</div>
                    </td>
                </tr>
            `;

            try {
                const resp = await fetchMarketCapData(page, mktCapPerPage);
                if (!resp || !resp.data || !resp.data.length) {
                    screenerTbody.innerHTML = `<tr><td colspan="5" style="text-align: center; color: #787b86; padding: 24px 12px;">Tidak ada data market cap.</td></tr>`;
                    return;
                }

                if (mktCapPageNum) mktCapPageNum.textContent = resp.page.toString();
                if (mktCapPageTotal) mktCapPageTotal.textContent = resp.total_pages.toString();
                if (mktCapItemTotal) mktCapItemTotal.textContent = resp.total.toString();
                if (prevBtn) {
                    prevBtn.disabled = resp.page <= 1;
                    prevBtn.style.opacity = resp.page <= 1 ? '0.5' : '1';
                    prevBtn.style.cursor = resp.page <= 1 ? 'not-allowed' : 'pointer';
                }
                if (nextBtn) {
                    nextBtn.disabled = resp.page >= resp.total_pages;
                    nextBtn.style.opacity = resp.page >= resp.total_pages ? '0.5' : '1';
                    nextBtn.style.cursor = resp.page >= resp.total_pages ? 'not-allowed' : 'pointer';
                }

                screenerTbody.innerHTML = resp.data.map((item, idx) => {
                    const rank = (resp.page - 1) * resp.per_page + idx + 1;
                    const priceFormatted = item.close ? Number(item.close).toLocaleString('id-ID') : '-';
                    const compName = item.name || stockNameMap.get(item.code) || '';
                    const shortName = compName ? (compName.length > 20 ? compName.substring(0, 18) + '...' : compName) : '';
                    const lotsData = formatLotsShort(item.listed_shares);
                    const totalLotsExact = item.listed_shares ? Math.round(item.listed_shares / 100).toLocaleString('id-ID') + ' lot' : '-';
                    const totalSharesExact = item.listed_shares ? Number(item.listed_shares).toLocaleString('id-ID') + ' lembar' : '-';
                    return `
                        <tr class="screener-row mktcap-row" data-symbol="${item.code}" style="cursor: pointer;">
                            <td>
                                <div style="font-weight: 700; color: #131722; font-size: 12px;">${item.code}</div>
                                <div style="font-size: 9.5px; color: #787b86;">#${rank}</div>
                            </td>
                            <td>
                                <div style="font-size: 11px; color: #2a2e39; font-weight: 500;" title="${compName}">${shortName}</div>
                                <div class="mktcap-price" style="font-size: 11px; color: #2962FF; font-weight: 600;">Rp ${priceFormatted}</div>
                            </td>
                            <td style="text-align: right;">
                                <div style="font-weight: 700; color: #131722; font-size: 12px;">${item.market_cap_label || '-'}</div>
                                <div style="font-size: 9px; color: #787b86;">${(item.market_cap_label || '').endsWith('T') ? 'Triliun IDR' : ((item.market_cap_label || '').endsWith('M') ? 'Miliar IDR' : 'IDR')}</div>
                            </td>
                            <td style="text-align: right;" title="${totalLotsExact} (${totalSharesExact})">
                                <div style="font-weight: 600; color: #434651; font-size: 11px;">${lotsData.val}</div>
                                <div style="font-size: 9px; color: #787b86;">${lotsData.sub}</div>
                            </td>
                            <td style="text-align: right;">
                                <span style="font-size: 10px; padding: 2px 5px; border-radius: 4px; background: #eef3ff; color: #2962FF; font-weight: 700;">
                                    ${item.turnover_ratio_label || '0.00%'}
                                </span>
                            </td>
                        </tr>
                    `;
                }).join('');

                // Row click listener to switch chart
                screenerTbody.querySelectorAll('.mktcap-row').forEach(row => {
                    row.addEventListener('click', () => {
                        const sym = row.getAttribute('data-symbol');
                        if (sym) {
                            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
                            if (tInput) {
                                tInput.value = sym;
                                tInput.dispatchEvent(new Event('change'));
                            }
                        }
                    });
                });
            } catch (err: any) {
                screenerTbody.innerHTML = `
                    <tr>
                        <td colspan="5" style="text-align: center; color: #ef5350; padding: 24px 12px; font-size: 12px;">
                            <div style="font-size: 18px; margin-bottom: 6px;">⚠️</div>
                            <div>Gagal memuat data Market Cap (${err.message || 'Error'})</div>
                        </td>
                    </tr>
                `;
            }
        }

        interface MoverItem {
            code: string;
            last_price: number;
            change: number;
            change_pct: number;
            freq: number;
            lot: number;
            value: number;
        }

        interface MoversResponse {
            by: string;
            gainers?: MoverItem[];
            losers?: MoverItem[];
            top?: MoverItem[];
            count: number;
            market: {
                status: string;
                label: string;
            };
        }

        const moversCache = new Map<string, { data: MoversResponse; timestamp: number }>();
        let currentMoversType: 'gainer' | 'loser' | 'value' | 'volume' | 'freq' | null = null;

        async function fetchMovers(by: 'chg' | 'value' | 'lot' | 'freq', forceRefresh = false): Promise<MoversResponse | null> {
            const now = Date.now();
            const cached = moversCache.get(by);
            if (!forceRefresh && cached && (now - cached.timestamp < 15000)) {
                return cached.data;
            }

            try {
                const res = await fetchArjumApi(`/api/movers?by=${by}&n=20`);
                if (res.ok) {
                    const data: MoversResponse = await res.json();
                    if (data) {
                        moversCache.set(by, { data, timestamp: Date.now() });
                        return data;
                    }
                }
            } catch (err) {
                console.warn(`[Movers API] Error fetching /api/movers?by=${by}:`, err);
            }
            return null;
        }

        async function renderMoversTab(type: 'gainer' | 'loser' | 'value' | 'volume' | 'freq') {
            currentMoversType = type;
            restoreStandardScreenerHeader();

            let byParam: 'chg' | 'value' | 'lot' | 'freq' = 'chg';
            if (type === 'value') byParam = 'value';
            else if (type === 'volume') byParam = 'lot';
            else if (type === 'freq') byParam = 'freq';

            screenerTbody.innerHTML = `
                <tr>
                    <td colspan="6" style="text-align: center; color: #787b86; padding: 28px 12px; font-size: 12px;">
                        <div style="font-size: 18px; margin-bottom: 6px;">⏳</div>
                        <div>Memuat data peringkat harian (${type})...</div>
                    </td>
                </tr>
            `;

            const resp = await fetchMovers(byParam);
            let items: MoverItem[] = [];

            if (resp) {
                if (type === 'gainer') items = resp.gainers || [];
                else if (type === 'loser') items = resp.losers || [];
                else items = resp.top || [];
            }

            if (!items || items.length === 0) {
                if (type === 'gainer') {
                    sortKey = 'change_percentage'; sortDir = 'desc';
                } else if (type === 'loser') {
                    sortKey = 'change_percentage'; sortDir = 'asc';
                } else if (type === 'value') {
                    sortKey = 'value'; sortDir = 'desc';
                } else if (type === 'volume') {
                    sortKey = 'volume'; sortDir = 'desc';
                } else if (type === 'freq') {
                    sortKey = 'frequency'; sortDir = 'desc';
                }
                renderScreener();
                return;
            }

            screenerTbody.innerHTML = items.map(item => {
                const sym = item.code;
                const effectiveChgPct = item.change_pct || 0;
                const chgColor = effectiveChgPct > 0 ? 'text-green' : (effectiveChgPct < 0 ? 'text-red' : '');
                const chgSign = effectiveChgPct > 0 ? '+' : '';
                const compName = stockNameMap.get(sym) || '';
                const scrObj = screenerMap.get(sym);
                const notationHtml = scrObj ? getNotationBadgeHtml(scrObj) : '';
                const priceFormatted = item.last_price ? Number(item.last_price).toLocaleString('en-US') : '0';
                const priceDisplay = `${priceFormatted} (${chgSign}${effectiveChgPct.toFixed(2)}%)`;
                const netForeign = scrObj ? scrObj.net_foreign : 0;
                const nfColor = netForeign > 0 ? 'text-green' : (netForeign < 0 ? 'text-red' : '');

                if (scrObj) {
                    scrObj.price = item.last_price;
                    scrObj.change_percentage = effectiveChgPct;
                    scrObj.change = item.change;
                    scrObj.volume = item.lot;
                    scrObj.value = item.value;
                    scrObj.frequency = item.freq;
                }

                return `<tr class="screener-row" data-symbol="${sym}" style="cursor: pointer;">
                    <td class="symbol-cell" title="${sym}${compName ? ' - ' + compName : ''}">
                        <span class="symbol-icon">${sym.slice(0, 1)}</span>
                        <span class="symbol-name">${sym}</span>
                        ${notationHtml}
                    </td>
                    <td class="text-right ${chgColor}">${priceDisplay}</td>
                    <td class="text-right">${formatNumber(item.value)}</td>
                    <td class="text-right">${formatNumber(item.lot)}</td>
                    <td class="text-right">${formatNumber(item.freq)}</td>
                    <td class="text-right ${nfColor}">${formatNumber(netForeign)}</td>
                </tr>`;
            }).join('');
        }

        function updateFinancialsActiveSymbol() {
            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
            const sym = (tInput?.value || 'BBCA').toUpperCase();
            const compName = stockNameMap.get(sym) || '';
            if (finActiveSymLabel) {
                finActiveSymLabel.textContent = sym;
                finActiveSymLabel.title = compName ? `${sym} - ${compName}` : sym;
            }
            const sub = currentFinReportType === 'INCOME_STATEMENT' ? 'Laba Rugi' : (currentFinReportType === 'BALANCE_SHEET' ? 'Neraca' : 'Arus Kas');
            if (finReportSubtitle) finReportSubtitle.textContent = `${sub} • ${currentFinPeriod === 'quarterly' ? 'Kuartal' : 'Tahunan'}`;
            updateFinancialsMarketCapBar(sym);
        }

        function loadFinancialsForActiveSymbol(forceRefresh = false) {
            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
            const sym = (tInput?.value || 'BBCA').toUpperCase();
            updateFinancialsMarketCapBar(sym);
            fetchStockFinancials(sym, currentFinReportType, currentFinPeriod, forceRefresh);
        }

        async function fetchStockFinancials(symbol: string, reportType = currentFinReportType, period = currentFinPeriod, forceRefresh = false) {
            const cacheKey = `${symbol}_${reportType}_${period}`;
            updateFinancialsActiveSymbol();

            if (!forceRefresh) {
                if (financialsCache.has(cacheKey)) {
                    renderFinancialsData(symbol, financialsCache.get(cacheKey)!);
                    return;
                }
                try {
                    const sess = sessionStorage.getItem(`fin_${cacheKey}`);
                    if (sess) {
                        const parsed = JSON.parse(sess);
                        financialsCache.set(cacheKey, parsed);
                        renderFinancialsData(symbol, parsed);
                        return;
                    }
                } catch (_) {}
            }

            if (financialsLoading) financialsLoading.style.display = 'block';
            if (financialsTableContainer) financialsTableContainer.innerHTML = '';
            if (financialsKpiContainer) financialsKpiContainer.innerHTML = '';

            try {
                const res = await fetchArjumApi(`/api/financial-statements/${symbol}?report_type=${reportType}&period=${period}&limit=16`);
                if (!res || !res.ok) {
                    throw new Error(`Gagal mengambil data (${res ? res.status : 'Network error'})`);
                }

                const data: FinancialStatementResponse = await res.json();
                financialsCache.set(cacheKey, data);
                try {
                    sessionStorage.setItem(`fin_${cacheKey}`, JSON.stringify(data));
                } catch (_) {}

                renderFinancialsData(symbol, data);
            } catch (err: any) {
                console.error("[Financials] Error fetching data:", err);
                if (financialsTableContainer) {
                    financialsTableContainer.innerHTML = `
                        <div style="padding: 24px 12px; text-align: center; color: #ef5350;">
                            <div style="font-size: 18px; margin-bottom: 6px;">⚠️</div>
                            <div style="font-weight: 600; font-size: 12px;">Gagal memuat laporan keuangan ${symbol}</div>
                            <div style="font-size: 11px; color: #787b86; margin-top: 4px;">${err.message || 'Periksa koneksi atau API Key Anda.'}</div>
                        </div>
                    `;
                }
            } finally {
                if (financialsLoading) financialsLoading.style.display = 'none';
            }
        }

        function renderFinancialsData(symbol: string, json: FinancialStatementResponse) {
            if (!financialsKpiContainer || !financialsTableContainer) return;
            const items = json?.items || [];

            if (!items.length) {
                updateFinancialsMarketCapBar(symbol);
                const finValBar = document.getElementById('financials-valuation-bar');
                if (finValBar) finValBar.style.display = 'none';
                financialsKpiContainer.innerHTML = '';
                financialsTableContainer.innerHTML = `
                    <div style="color: #787b86; padding: 24px 12px; text-align: center; font-size: 12px;">
                        <div style="font-size: 18px; margin-bottom: 6px;">📄</div>
                        <div>Tidak ada data laporan keuangan untuk ${symbol} (${json.report_type})</div>
                    </div>
                `;
                return;
            }

            // 0. Market Cap & Saham Beredar Bar & Valuation Bar
            updateFinancialsMarketCapBar(symbol);
            updateFinancialsValuationBar(symbol, json);

            // 1. KPI Cards (Unified into Hairline Grid above; hide floating cards)
            if (financialsKpiContainer) {
                financialsKpiContainer.style.display = 'none';
                financialsKpiContainer.innerHTML = '';
            }

            // 2. Metric Table
            const metricKeys: string[] = [];
            const containerKeysToIgnore = ['aset', 'liabilitas_dan_ekuitas', 'liabilitas_dana_syirkah_temporer_dan_ekuitas'];
            if (json.report_type === 'BALANCE_SHEET') {
                const essentialBalanceKeys = [
                    'total_aset',
                    'aset_lancar',
                    'aset_tidak_lancar',
                    'kas_dan_setara_kas',
                    'total_liabilitas',
                    'liabilitas_jangka_pendek',
                    'liabilitas_jangka_panjang',
                    'total_ekuitas',
                    'total_liabilitas_dan_ekuitas'
                ];
                for (const k of essentialBalanceKeys) {
                    const hasVal = items.some(it => {
                        const val = getFinancialItemValue(it, k, json.report_type);
                        return extractNumericValue(val) !== null;
                    });
                    if (hasVal && !metricKeys.includes(k)) {
                        metricKeys.push(k);
                    }
                }
            }

            items.forEach(it => {
                if (it.data) {
                    Object.keys(it.data).forEach(k => {
                        if (json.report_type === 'BALANCE_SHEET' && containerKeysToIgnore.includes(k)) {
                            return;
                        }
                        if (!metricKeys.includes(k)) metricKeys.push(k);
                    });
                }
            });

            // Prioritize standard order if present
            const preferredOrder = [
                'penjualan_dan_pendapatan_usaha', 'pendapatan', 'pendapatan_usaha', 'penjualan', 'beban_pokok_penjualan_dan_pendapatan', 'beban_pokok_pendapatan',
                'laba_bruto', 'laba_kotor', 'beban_usaha', 'laba_usaha', 'laba_operasional', 'laba_rugi_sebelum_pajak_penghasilan', 'laba_sebelum_pajak',
                'laba_rugi', 'laba_bersih', 'laba_rugi_per_saham', 'eps',
                'total_aset', 'aset_lancar', 'aset_tidak_lancar', 'kas_dan_setara_kas', 'total_liabilitas', 'liabilitas_jangka_pendek', 'liabilitas_jangka_panjang', 'total_ekuitas', 'total_liabilitas_dan_ekuitas',
                'arus_kas_operasi', 'arus_kas_dari_aktivitas_operasi', 'arus_kas_investasi', 'arus_kas_dari_aktivitas_investasi', 'arus_kas_pendanaan', 'arus_kas_dari_aktivitas_pendanaan', 'kenaikan_penurunan_kas', 'kenaikan_penurunan_bersih_kas_dan_setara_kas', 'kas_awal_periode', 'kas_dan_setara_kas_arus_kas_awal_periode', 'kas_akhir_periode', 'kas_dan_setara_kas_arus_kas_akhir_periode'
            ];
            metricKeys.sort((a, b) => {
                const idxA = preferredOrder.indexOf(a.toLowerCase());
                const idxB = preferredOrder.indexOf(b.toLowerCase());
                if (idxA !== -1 && idxB !== -1) return idxA - idxB;
                if (idxA !== -1) return -1;
                if (idxB !== -1) return 1;
                return a.localeCompare(b);
            });

            let tableHtml = `
                <table class="fin-table">
                    <thead>
                        <tr>
                            <th>Metrik</th>
                            ${items.map(it => `<th>${it.label}</th>`).join('')}
                        </tr>
                    </thead>
                    <tbody>
            `;

            let hasPer1000InTable = false;
            metricKeys.forEach(k => {
                const label = formatMetricLabel(k);
                const gKey = getGlossaryKeyForMetric(k);
                const isEps = k.toLowerCase().includes('per_saham') || k.toLowerCase() === 'eps';
                tableHtml += `
                    <tr>
                        <td class="fin-glossary-hover" data-glossary="${gKey}" title="${k}">${label}</td>
                        ${items.map(it => {
                            const v = getFinancialItemValue(it, k, json.report_type);
                            const num = extractNumericValue(v);
                            let formatted = '-';
                            let tooltip = '-';
                            let isNeg = false;

                            if (isEps) {
                                const itNi = extractFinancialNetIncome(it.data);
                                const epsObj = getEpsInfo(v, symbol, itNi);
                                if (epsObj.normNum !== null) {
                                    if (epsObj.isPer1000) hasPer1000InTable = true;
                                    formatted = `Rp ${epsObj.formatted}${epsObj.isPer1000 ? '*' : ''}`;
                                    tooltip = epsObj.isPer1000
                                        ? `Rp ${epsObj.normNum.toFixed(2)}/saham (Asli di XBRL: Rp ${epsObj.rawNum?.toLocaleString('id-ID')} per 1.000 saham)`
                                        : `Rp ${Number(epsObj.normNum).toLocaleString('en-US')}`;
                                    isNeg = epsObj.normNum < 0;
                                }
                            } else {
                                formatted = formatRupiahFin(v);
                                tooltip = num !== null ? 'Rp ' + Number(num).toLocaleString('en-US') : '-';
                                isNeg = num !== null && num < 0;
                            }
                            return `<td style="${isNeg ? 'color: #e05252; font-weight: 500;' : ''}" title="${tooltip}">${formatted}</td>`;
                        }).join('')}
                    </tr>
                `;
            });

            tableHtml += `</tbody></table>`;
            if (hasPer1000InTable) {
                tableHtml += `
                    <div style="padding: 6px 10px; font-size: 10px; color: #d97706; background: #fffbeb; border-top: 1px solid #fef3c7;">
                        *Laba per Saham dinormalisasi dari basis pelaporan per 1.000 saham (XBRL IDX).
                    </div>
                `;
            }
            financialsTableContainer.innerHTML = tableHtml;
        }

        // Financials Controls Listeners
        finPeriodQBtn?.addEventListener('click', () => {
            currentFinPeriod = 'quarterly';
            finPeriodQBtn.classList.add('active');
            finPeriodABtn?.classList.remove('active');
            loadFinancialsForActiveSymbol();
        });

        finPeriodABtn?.addEventListener('click', () => {
            currentFinPeriod = 'annually';
            finPeriodABtn.classList.add('active');
            finPeriodQBtn?.classList.remove('active');
            loadFinancialsForActiveSymbol();
        });

        finRefreshBtn?.addEventListener('click', () => {
            finRefreshBtn.classList.add('spin');
            setTimeout(() => finRefreshBtn.classList.remove('spin'), 800);
            loadFinancialsForActiveSymbol(true);
            showToast('Memperbarui data laporan keuangan...');
        });

        finTypeIncomeBtn?.addEventListener('click', () => {
            currentFinReportType = 'INCOME_STATEMENT';
            finTypeIncomeBtn.classList.add('active');
            finTypeBalanceBtn?.classList.remove('active');
            finTypeCashBtn?.classList.remove('active');
            loadFinancialsForActiveSymbol();
        });

        finTypeBalanceBtn?.addEventListener('click', () => {
            currentFinReportType = 'BALANCE_SHEET';
            finTypeBalanceBtn.classList.add('active');
            finTypeIncomeBtn?.classList.remove('active');
            finTypeCashBtn?.classList.remove('active');
            loadFinancialsForActiveSymbol();
        });

        finTypeCashBtn?.addEventListener('click', () => {
            currentFinReportType = 'CASH_FLOW_REPORT';
            finTypeCashBtn.classList.add('active');
            finTypeIncomeBtn?.classList.remove('active');
            finTypeBalanceBtn?.classList.remove('active');
            loadFinancialsForActiveSymbol();
        });

        finValBandsBtn?.addEventListener('click', () => {
            isValBandsActive = !isValBandsActive;
            if (isValBandsActive) {
                finValBandsBtn.classList.add('active');
                const tInput = document.getElementById('ticker-input') as HTMLInputElement;
                const sym = (tInput?.value || 'BBCA').toUpperCase();
                updateValuationChartOverlay(sym);
                showToast(`📐 Valuation Bands diaktifkan untuk ${sym}`);
            } else {
                finValBandsBtn.classList.remove('active');
                clearValuationPriceLines();
                showToast('Valuation Bands dinonaktifkan');
            }
        });

        // Initialize Financial Glossary Popover Tooltips
        setupFinancialGlossaryTooltips();

        // =========================================================================
        // BROKER SUMMARY & BANDARMOLOGY INVENTORY (IDXEDGEPRO REST API)
        // =========================================================================
        const ALL_IDX_BROKERS = [
            'AD','AG','AH','AI','AK','AN','AO','AP','AR','AT','AZ','BB','BF','BK','BQ','BR','BZ',
            'CC','CD','CP','CS','DH','DM','DP','DR','DX','EP','FO','FS','GA','GR','HD','HP','IC',
            'IF','II','IN','IP','IT','IU','JB','KI','KK','KS','KZ','LG','LH','LS','MG','MI','MS',
            'MU','NI','OD','PC','PD','PF','PG','PI','PK','PO','PP','PS','QA','RB','RF','RG','RO',
            'RS','RX','SF','SH','SQ','SS','SW','TF','TP','TS','TX','XA','XC','XL','YB','YJ','YP',
            'YU','ZP'
        ];

        interface BrokerSummaryLevelSide {
            broker_code?: string;
            broker_name?: string;
            bval?: number;
            bvol?: number;
            bfrq?: number;
            bavg?: number;
            sval?: number;
            svol?: number;
            sfrq?: number;
            savg?: number;
        }

        interface BrokerSummaryLevel {
            buy?: BrokerSummaryLevelSide;
            sell?: BrokerSummaryLevelSide;
        }

        interface BrokerSummaryItem {
            broker_code: string;
            broker_name?: string;
            bval?: number;
            bvol?: number;
            bfrq?: number;
            sval?: number;
            svol?: number;
            sfrq?: number;
            nval?: number;
            nvol?: number;
        }

        interface BrokerSummaryResponse {
            stock_code: string;
            brokers?: BrokerSummaryItem[];
            broker_levels?: BrokerSummaryLevel[];
            broker_start_date?: string;
            broker_end_date?: string;
            broker_date_min?: string;
            broker_date_max?: string;
            broker_net?: boolean;
            flow?: string;
        }

        interface BrokerAccumulationPoint {
            date: string;
            nval: number;
            nvol: number;
            cum_nval: number;
            bavg: number;
            savg: number;
        }

        interface BrokerAccumulationSeries {
            broker_code: string;
            broker_name?: string;
            points: BrokerAccumulationPoint[];
        }

        interface BrokerAccumulationTopItem {
            broker_code: string;
            broker_name?: string;
            total_nval: number;
        }

        interface BrokerAccumulationResponse {
            code: string;
            start_date: string;
            end_date: string;
            series: BrokerAccumulationSeries[];
            top_buyers?: BrokerAccumulationTopItem[];
            top_sellers?: BrokerAccumulationTopItem[];
        }

        interface ReconstructedBrokerPosition {
            broker_code: string;
            broker_name: string;
            position: number; // estimated position in lots (>= 0)
            implied_initial_position: number; // shortfall in lots
            average_cost: number | null; // weighted average acquisition cost in IDR
            total_net_value: number; // IDR
            total_bought_lots: number;
            total_sold_lots: number;
            percent_free_float: number; // % of free float
            position_source: 'observed' | 'implied_initial' | 'mixed' | 'none';
            last_active_date?: string;
        }

        type BsPeriod = '1d' | '1w' | '1m' | '3m' | 'ytd' | '1y' | 'all' | 'custom';
        type BsView = 'summary' | 'inventory';
        type BsFlow = 'all' | 'F' | 'D';

        let currentBsPeriod: BsPeriod = '1m';
        let currentBsView: BsView = 'summary';
        let currentBsFlow: BsFlow = 'all';
        let bsCustomStartDate = '';
        let bsCustomEndDate = '';
        let bsSearchQuery = '';

        const brokerSummaryCache = new Map<string, BrokerSummaryResponse>();
        const brokerAccumulationCache = new Map<string, BrokerAccumulationResponse>();
        let lastReconstructedPositions: ReconstructedBrokerPosition[] = [];

        function formatBsValShort(val: number): string {
            if (!val || isNaN(val)) return '-';
            const abs = Math.abs(val);
            const sign = val < 0 ? '-' : (val > 0 ? '+' : '');
            if (abs >= 1e12) return `${sign}${(abs / 1e12).toFixed(2)} T`;
            if (abs >= 1e9) return `${sign}${(abs / 1e9).toFixed(2)} B`;
            if (abs >= 1e6) return `${sign}${(abs / 1e6).toFixed(1)} M`;
            return `${sign}${Math.round(abs).toLocaleString('id-ID')}`;
        }

        function formatBsLots(lots: number): string {
            if (!lots || isNaN(lots)) return '0 lot';
            const abs = Math.abs(lots);
            if (abs >= 1e6) return `${(lots / 1e6).toFixed(2)}M lot`;
            if (abs >= 1e3) return `${(lots / 1e3).toFixed(1)}K lot`;
            return `${Math.round(lots).toLocaleString('id-ID')} lot`;
        }

        function formatBsLotsShort(lots: number): string {
            if (!lots || isNaN(lots)) return '-';
            const abs = Math.abs(lots);
            if (abs >= 1e6) return `${(lots / 1e6).toFixed(2)}M`;
            if (abs >= 1e3) return `${(lots / 1e3).toFixed(1)}K`;
            return `${Math.round(lots).toLocaleString('id-ID')}`;
        }

        function getBsDateRange(period: BsPeriod): { startDate: string; endDate: string } {
            const now = new Date();
            const endStr = now.toISOString().split('T')[0];
            let startStr = endStr;

            if (period === '1d') {
                startStr = endStr;
            } else if (period === '1w') {
                const d = new Date(now.getTime() - 7 * 86400000);
                startStr = d.toISOString().split('T')[0];
            } else if (period === '1m') {
                const d = new Date(now.getTime() - 30 * 86400000);
                startStr = d.toISOString().split('T')[0];
            } else if (period === '3m') {
                const d = new Date(now.getTime() - 90 * 86400000);
                startStr = d.toISOString().split('T')[0];
            } else if (period === 'ytd') {
                startStr = `${now.getFullYear()}-01-01`;
            } else if (period === '1y') {
                const d = new Date(now.getTime() - 365 * 86400000);
                startStr = d.toISOString().split('T')[0];
            } else if (period === 'all') {
                startStr = '2020-01-02';
            } else if (period === 'custom') {
                startStr = bsCustomStartDate || endStr;
                const end = bsCustomEndDate || endStr;
                return { startDate: startStr, endDate: end };
            }
            return { startDate: startStr, endDate: endStr };
        }

        async function updateBsMarketCapBar(symbol: string) {
            if (!bsMarketcapBar) return;
            const symUpper = symbol.toUpperCase();
            if (stockMarketCapMap.size === 0) {
                await loadMarketCapData();
            }
            const mktItem = stockMarketCapMap.get(symUpper);
            if (mktItem) {
                const formattedMktCap = formatIdrNominalLabel(mktItem.market_cap, mktItem.market_cap_label);
                const formattedLots = formatLotsWidget(mktItem.listed_shares);
                const totalLotsExact = mktItem.listed_shares ? Math.round(mktItem.listed_shares / 100).toLocaleString('id-ID') + ' lot' : '-';
                const totalSharesExact = mktItem.listed_shares ? Number(mktItem.listed_shares).toLocaleString('id-ID') + ' lembar' : '-';
                bsMarketcapBar.style.display = 'flex';
                bsMarketcapBar.className = 'meta-strip';
                bsMarketcapBar.innerHTML = `
                    <span>Mkt Cap: <strong>Rp ${formattedMktCap}</strong></span>
                    <span class="dot">•</span>
                    <span title="${totalLotsExact} (${totalSharesExact})">Free Float: <strong>${formattedLots}</strong></span>
                    <span class="dot">•</span>
                    <span>Turnover: <strong>${mktItem.turnover_ratio_label || '0.00%'}</strong></span>
                `;
            } else {
                bsMarketcapBar.style.display = 'none';
            }
        }

        function updateBsActiveSymbol() {
            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
            const sym = (tInput?.value || 'BBCA').toUpperCase();
            const compName = stockNameMap.get(sym) || '';
            if (bsActiveSymLabel) {
                bsActiveSymLabel.textContent = sym;
                bsActiveSymLabel.title = compName ? `${sym} - ${compName}` : sym;
            }
            const range = getBsDateRange(currentBsPeriod);
            const periodLabel = currentBsPeriod.toUpperCase();
            if (bsReportSubtitle) {
                bsReportSubtitle.textContent = compName ? `${compName} • ${periodLabel}` : `Bandarmology • ${periodLabel} (${range.startDate} s/d ${range.endDate})`;
                bsReportSubtitle.title = `Bandarmology • ${periodLabel} (${range.startDate} s/d ${range.endDate})`;
            }
            updateBsMarketCapBar(sym);
        }

        function reconstructBrokerPositions(
            accumulationData: BrokerAccumulationResponse,
            symbol: string
        ): ReconstructedBrokerPosition[] {
            const mktItem = stockMarketCapMap.get(symbol.toUpperCase());
            const listedLots = mktItem && mktItem.listed_shares ? (mktItem.listed_shares / 100) : 0;

            const result: ReconstructedBrokerPosition[] = [];

            for (const s of (accumulationData.series || [])) {
                const brokerCode = s.broker_code;
                const brokerName = brokerNameMap.get(brokerCode) || s.broker_name || brokerCode;
                const points = (s.points || []).slice().sort((a, b) => a.date.localeCompare(b.date));

                let position = 0.0;
                let impliedInitial = 0.0;
                let avgCost: number | null = null;
                let totalNetVal = 0.0;
                let totalBought = 0.0;
                let totalSold = 0.0;
                let lastDate = '';

                for (const pt of points) {
                    lastDate = pt.date;
                    totalNetVal += pt.nval || 0;
                    const netShares = pt.nvol || 0;
                    const netLots = netShares / 100;

                    if (netLots > 0) {
                        // Net BUY
                        const buyLot = netLots;
                        const buyPrice = pt.bavg > 0 ? pt.bavg : (netShares > 0 ? (pt.nval / netShares) : 0);
                        totalBought += buyLot;
                        if (position <= 0 || avgCost === null) {
                            avgCost = buyPrice;
                        } else {
                            avgCost = (position * avgCost + buyLot * buyPrice) / (position + buyLot);
                        }
                        position += buyLot;
                    } else if (netLots < 0) {
                        // Net SELL
                        const sellLot = Math.abs(netLots);
                        totalSold += sellLot;
                        const rawNet = position - sellLot;
                        if (rawNet < 0) {
                            const shortfall = -rawNet;
                            impliedInitial += shortfall;
                            position = 0;
                            avgCost = null;
                        } else {
                            position = rawNet;
                            if (position === 0) {
                                avgCost = null;
                            }
                            // Average cost strictly unchanged when position remains > 0
                        }
                    }
                }

                let source: 'observed' | 'implied_initial' | 'mixed' | 'none' = 'none';
                if (impliedInitial > 0 && totalBought > 0) {
                    source = 'mixed';
                } else if (impliedInitial > 0) {
                    source = 'implied_initial';
                } else if (totalBought > 0) {
                    source = 'observed';
                }

                const pctFreeFloat = listedLots > 0 ? (position / listedLots) * 100 : 0;

                result.push({
                    broker_code: brokerCode,
                    broker_name: brokerName,
                    position: Math.round(position),
                    implied_initial_position: Math.round(impliedInitial),
                    average_cost: avgCost ? Math.round(avgCost) : null,
                    total_net_value: totalNetVal,
                    total_bought_lots: Math.round(totalBought),
                    total_sold_lots: Math.round(totalSold),
                    percent_free_float: pctFreeFloat,
                    position_source: source,
                    last_active_date: lastDate
                });
            }

            // Sort descending by position, then by absolute net value
            result.sort((a, b) => b.position - a.position || Math.abs(b.total_net_value) - Math.abs(a.total_net_value));
            return result;
        }

        async function fetchBrokerSummaryData(symbol: string, startDate: string, endDate: string, flow: BsFlow = currentBsFlow, forceRefresh = false): Promise<BrokerSummaryResponse | null> {
            const cacheKey = `${symbol}_${startDate}_${endDate}_${flow}`;
            if (!forceRefresh && brokerSummaryCache.has(cacheKey)) {
                return brokerSummaryCache.get(cacheKey)!;
            }

            const flowParam = flow && flow !== 'all' ? `&flow=${flow}` : '';
            const res = await fetchArjumApi(`/api/broker-summary/${symbol}?start_date=${startDate}&end_date=${endDate}&all_data=true${flowParam}`);

            if (!res || !res.ok) {
                throw new Error(`Broker summary HTTP ${res ? res.status : 'Network error'}`);
            }

            const data: BrokerSummaryResponse = await res.json();
            brokerSummaryCache.set(cacheKey, data);
            return data;
        }

        async function fetchBrokerAccumulationData(symbol: string, startDate: string, endDate: string, forceRefresh = false): Promise<BrokerAccumulationResponse | null> {
            const cacheKey = `${symbol}_${startDate}_${endDate}`;
            if (!forceRefresh && brokerAccumulationCache.has(cacheKey)) {
                return brokerAccumulationCache.get(cacheKey)!;
            }

            const brokersQuery = ALL_IDX_BROKERS.join(',');
            const res = await fetchArjumApi(`/api/broker-accumulation/${symbol}?brokers=${brokersQuery}&start_date=${startDate}&end_date=${endDate}&top=5`);

            if (!res || !res.ok) {
                throw new Error(`Broker accumulation HTTP ${res ? res.status : 'Network error'}`);
            }

            const data: BrokerAccumulationResponse = await res.json();
            brokerAccumulationCache.set(cacheKey, data);
            return data;
        }

        async function loadBandarmologyForActiveSymbol(forceRefresh = false) {
            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
            const sym = (tInput?.value || 'BBCA').toUpperCase();
            updateBsActiveSymbol();

            if (bsLoading) bsLoading.style.display = 'block';
            if (bsConcentrationCard) bsConcentrationCard.innerHTML = '';
            if (bsViewContainer) bsViewContainer.innerHTML = '';

            const range = getBsDateRange(currentBsPeriod);

            try {
                if (currentBsView === 'summary') {
                    const data = await fetchBrokerSummaryData(sym, range.startDate, range.endDate, currentBsFlow, forceRefresh);
                    if (bsLoading) bsLoading.style.display = 'none';
                    if (data) {
                        renderBandarmologySummaryView(data, sym);
                    }
                } else {
                    const accData = await fetchBrokerAccumulationData(sym, range.startDate, range.endDate, forceRefresh);
                    if (bsLoading) bsLoading.style.display = 'none';
                    if (accData) {
                        lastReconstructedPositions = reconstructBrokerPositions(accData, sym);
                        if (bsBrokerCount) bsBrokerCount.textContent = lastReconstructedPositions.length.toString();
                        renderBrokerInventoryView();
                    }
                }
            } catch (err: any) {
                console.error("[Bandarmology] Error loading data:", err);
                if (bsLoading) bsLoading.style.display = 'none';
                if (bsViewContainer) {
                    bsViewContainer.innerHTML = `
                        <div style="padding: 24px 12px; text-align: center; color: #ef5350; font-size: 12px;">
                            <div style="font-size: 20px; margin-bottom: 6px;">⚠️</div>
                            <div style="font-weight: 600;">Gagal memuat data Bandarmology</div>
                            <div style="font-size: 11px; color: #787b86; margin-top: 4px;">${err.message || 'Network error'}</div>
                            <button id="bs-retry-btn" style="margin-top: 10px; padding: 4px 10px; font-size: 11px; background: #2962FF; color: #fff; border: none; border-radius: 4px; cursor: pointer; font-weight: 600;">Coba Lagi</button>
                        </div>
                    `;
                    document.getElementById('bs-retry-btn')?.addEventListener('click', () => loadBandarmologyForActiveSymbol(true));
                }
            }
        }

        function renderBandarmologySummaryView(data: BrokerSummaryResponse, _symbol: string) {
            if (!bsViewContainer || !bsConcentrationCard) return;

            const levels = data.broker_levels || [];
            const brokers = data.brokers || [];

            // Compute Top 1, 3, 5 Concentration from brokers sorted by net value
            const buyers = brokers.filter(b => (b.nval || 0) > 0).sort((a, b) => (b.nval || 0) - (a.nval || 0));
            const sellers = brokers.filter(b => (b.nval || 0) < 0).sort((a, b) => (a.nval || 0) - (b.nval || 0));

            const top1BuyerNval = buyers.length > 0 ? (buyers[0].nval || 0) : 0;
            const top3BuyerNval = buyers.slice(0, 3).reduce((acc, b) => acc + (b.nval || 0), 0);
            const top5BuyerNval = buyers.slice(0, 5).reduce((acc, b) => acc + (b.nval || 0), 0);

            const top1SellerNval = sellers.length > 0 ? Math.abs(sellers[0].nval || 0) : 0;
            const top3SellerNval = sellers.slice(0, 3).reduce((acc, b) => acc + Math.abs(b.nval || 0), 0);
            const top5SellerNval = sellers.slice(0, 5).reduce((acc, b) => acc + Math.abs(b.nval || 0), 0);

            const diff1 = top1BuyerNval - top1SellerNval;
            const diff3 = top3BuyerNval - top3SellerNval;
            const diff5 = top5BuyerNval - top5SellerNval;

            // Total turnover in the period
            const totalBuyVal = brokers.reduce((acc, b) => acc + (b.bval || 0), 0);
            const totalSellVal = brokers.reduce((acc, b) => acc + (b.sval || 0), 0);
            const totalTurnover = Math.max(totalBuyVal, totalSellVal) || 1;

            // Bandar Detector Status determination
            let statusLabel = 'Neutral';
            let badgeText = 'Seimbang';
            let badgeClass = 'badge-neutral';
            let subText = diff3 >= 0 ? 'Akumulasi Tipis' : 'Distribusi Normal';
            const diff3Ratio = diff3 / totalTurnover;

            if (diff3Ratio > 0.12) {
                statusLabel = 'Big Acc';
                badgeText = 'Solid';
                badgeClass = 'badge-green';
                subText = 'Akumulasi Masif';
            } else if (diff3Ratio > 0.03) {
                statusLabel = 'Normal Acc';
                badgeText = 'Akum';
                badgeClass = 'badge-green';
                subText = 'Akumulasi Terdeteksi';
            } else if (diff3Ratio < -0.12) {
                statusLabel = 'Big Dist';
                badgeText = 'Heavy';
                badgeClass = 'badge-red';
                subText = 'Distribusi Masif';
            } else if (diff3Ratio < -0.03) {
                statusLabel = 'Normal Dist';
                badgeText = 'Distribusi';
                badgeClass = 'badge-red';
                subText = 'Distribusi Terdeteksi';
            }

            const periodLabel = currentBsPeriod === 'all' ? 'ALL 2020' : currentBsPeriod.toUpperCase();

            bsConcentrationCard.innerHTML = `
                <div class="section-header-strip">
                    <span>RINGKASAN BANDAR DETECTOR (PERIODE ${periodLabel})</span>
                    <span class="src-label">Data IDX</span>
                </div>
                <div class="hairline-grid-4">
                    <div class="g-cell">
                        <span class="g-label">STATUS BANDAR</span>
                        <div class="g-val-row">
                            <span class="g-val">${statusLabel}</span>
                            <span class="${badgeClass}">${badgeText}</span>
                        </div>
                        <span class="g-sub">${subText}</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">TOP 1 NET</span>
                        <span class="g-val">${formatBsValShort(diff1)}</span>
                        <span class="g-sub ${diff1 >= 0 ? 'up' : 'down'}">${diff1 >= 0 ? '▲ Buy > Sell' : '▼ Sell > Buy'}</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">TOP 3 NET</span>
                        <span class="g-val">${formatBsValShort(diff3)}</span>
                        <span class="g-sub ${diff3 >= 0 ? 'up' : 'down'}">${diff3 >= 0 ? '▲ Buy > Sell' : '▼ Sell > Buy'}</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">TOP 5 NET</span>
                        <span class="g-val">${formatBsValShort(diff5)}</span>
                        <span class="g-sub ${diff5 >= 0 ? 'up' : 'down'}">${diff5 >= 0 ? '▲ Buy > Sell' : '▼ Sell > Buy'}</span>
                    </div>
                </div>
            `;

            // Top Buyers vs Top Sellers Table Full-Bleed
            let tableHtml = `
                <div class="table-scroll" style="width: 100%; overflow-x: auto;">
                    <table class="fin-clean-table split-broker-table">
                        <thead>
                            <tr>
                                <th class="col-rank">#</th>
                                <th>BUYER</th>
                                <th class="num">LOT</th>
                                <th class="num">VAL</th>
                                <th class="num divider-right">AVG</th>
                                <th style="padding-left: 10px;">SELLER</th>
                                <th class="num">LOT</th>
                                <th class="num">VAL</th>
                                <th class="num">AVG</th>
                            </tr>
                        </thead>
                        <tbody>
            `;

            const maxRows = Math.max(levels.length, 1);
            for (let i = 0; i < maxRows; i++) {
                const lvl = levels[i] || {};
                const b = lvl.buy || {};
                const s = lvl.sell || {};

                const bCode = b.broker_code || '-';
                const bName = brokerNameMap.get(bCode) || b.broker_name || bCode;
                const bLotStr = b.bvol ? formatBsLotsShort(b.bvol / 100) : '-';
                const bValStr = b.bval ? formatBsValShort(b.bval) : '-';
                const bAvgStr = b.bavg ? Math.round(b.bavg).toLocaleString('en-US') : '-';

                const sCode = s.broker_code || '-';
                const sName = brokerNameMap.get(sCode) || s.broker_name || sCode;
                const sLotStr = s.svol ? formatBsLotsShort(s.svol / 100) : '-';
                const sValStr = s.sval ? formatBsValShort(s.sval) : '-';
                const sAvgStr = s.savg ? Math.round(s.savg).toLocaleString('en-US') : '-';

                const bDispName = bName.length > 12 ? bName.slice(0, 11) + '…' : bName;
                const sDispName = sName.length > 12 ? sName.slice(0, 11) + '…' : sName;

                tableHtml += `
                    <tr>
                        <td class="col-rank">${i + 1}</td>
                        <td title="${bCode} - ${bName}">
                            <span class="brk-code buy">${bCode}</span>
                            <span class="brk-name">${bDispName}</span>
                        </td>
                        <td class="num"><strong>${bLotStr}</strong></td>
                        <td class="num up">${bValStr}</td>
                        <td class="num muted divider-right">${bAvgStr}</td>
                        <td style="padding-left: 10px;" title="${sCode} - ${sName}">
                            <span class="brk-code sell">${sCode}</span>
                            <span class="brk-name">${sDispName}</span>
                        </td>
                        <td class="num"><strong>${sLotStr}</strong></td>
                        <td class="num down">${sValStr}</td>
                        <td class="num muted">${sAvgStr}</td>
                    </tr>
                `;
            }

            tableHtml += `</tbody></table></div>`;
            bsViewContainer.innerHTML = tableHtml;
        }

        function renderBrokerInventoryView() {
            if (!bsViewContainer || !bsConcentrationCard) return;

            const q = (bsSearchQuery || '').trim().toUpperCase();
            const filtered = q
                ? lastReconstructedPositions.filter(p => {
                    const bName = brokerNameMap.get(p.broker_code) || p.broker_name || '';
                    return p.broker_code.includes(q) || bName.toUpperCase().includes(q);
                })
                : lastReconstructedPositions;

            // Update broker count badge
            if (bsBrokerCount) bsBrokerCount.textContent = lastReconstructedPositions.length.toString();

            // Total inventory stats
            const totalTrackedLots = lastReconstructedPositions.reduce((acc, p) => acc + p.position, 0);
            const netHoldingBrokers = lastReconstructedPositions.filter(p => p.position > 0).length;
            const topHoldingBroker = lastReconstructedPositions.length > 0 ? lastReconstructedPositions[0] : null;
            const topHolderCode = topHoldingBroker ? topHoldingBroker.broker_code : '-';
            const topHolderName = topHoldingBroker ? (brokerNameMap.get(topHoldingBroker.broker_code) || topHoldingBroker.broker_name || topHoldingBroker.broker_code) : '';

            const periodLabel = currentBsPeriod === 'all' ? 'ALL 2020' : currentBsPeriod.toUpperCase();
            const accRatio = ((netHoldingBrokers / (lastReconstructedPositions.length || 1)) * 100).toFixed(1);
            const isAccMajority = netHoldingBrokers >= (lastReconstructedPositions.length / 2);

            bsConcentrationCard.innerHTML = `
                <div class="section-header-strip">
                    <span>RINGKASAN INVENTORI BROKER (RECONSTRUCTED • ${periodLabel})</span>
                    <span class="src-label">Data IDX</span>
                </div>
                <div class="hairline-grid-4">
                    <div class="g-cell">
                        <span class="g-label">TOTAL INVENTORY</span>
                        <span class="g-val">${formatBsLots(totalTrackedLots)}</span>
                        <span class="g-sub">Tracked in lots</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">TOP HOLDER</span>
                        <div class="g-val-row">
                            <span class="g-val" title="${topHolderName}">${topHolderCode}</span>
                            <span class="badge-green">${topHoldingBroker ? formatBsLotsShort(topHoldingBroker.position) + ' lot' : '-'}</span>
                        </div>
                        <span class="g-sub">${topHolderName.length > 16 ? topHolderName.slice(0, 15) + '…' : topHolderName}</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">TOP FLOAT SHARE</span>
                        <span class="g-val">${topHoldingBroker ? topHoldingBroker.percent_free_float.toFixed(2) + '%' : '-'}</span>
                        <span class="g-sub">Dari Free Float</span>
                    </div>
                    <div class="g-cell">
                        <span class="g-label">AKTIVITAS BROKER</span>
                        <div class="g-val-row">
                            <span class="g-val">${netHoldingBrokers} <small>/ ${lastReconstructedPositions.length}</small></span>
                            <span class="badge-green">${accRatio}%</span>
                        </div>
                        <span class="g-sub ${isAccMajority ? 'up' : 'down'}">${isAccMajority ? `▲ ${accRatio}% Net Buy` : '▼ Mayoritas Net Sell'}</span>
                    </div>
                </div>
            `;

            let tableHtml = `
                <div class="table-scroll" style="width: 100%; overflow-x: auto;">
                    <table class="fin-clean-table">
                        <thead>
                            <tr>
                                <th class="col-rank">#</th>
                                <th>Broker</th>
                                <th class="num" title="Estimated Position (Lots)">Estimated Pos</th>
                                <th class="num" title="% of Free Float Shares">% Float</th>
                                <th class="num" title="Weighted Average Acquisition Cost">Avg Cost</th>
                                <th class="num" title="Cumulative Net Transaction Value">Cum Net Val</th>
                                <th class="num" title="Implied Initial Position from Shortfall">Implied</th>
                            </tr>
                        </thead>
                        <tbody>
            `;

            if (filtered.length === 0) {
                tableHtml += `
                    <tr>
                        <td colspan="7" style="text-align: center; color: #787b86; padding: 24px 12px; font-size: 12px;">
                            Tidak ada broker ditemukan ${q ? `untuk pencarian "${q}"` : ''}
                        </td>
                    </tr>
                `;
            } else {
                filtered.forEach((p, idx) => {
                    const posFormatted = p.position > 0 ? formatBsLotsShort(p.position) + ' lot' : '0';
                    const floatStr = p.percent_free_float > 0 ? p.percent_free_float.toFixed(2) + '%' : '-';
                    const avgStr = p.average_cost ? `Rp ${Math.round(p.average_cost).toLocaleString('en-US')}` : '-';
                    const netValFormatted = formatBsValShort(p.total_net_value);
                    const netValClass = p.total_net_value > 0 ? 'up' : (p.total_net_value < 0 ? 'down' : 'muted');
                    const impliedStr = p.implied_initial_position > 0 ? formatBsLotsShort(p.implied_initial_position) : '-';

                    const bName = brokerNameMap.get(p.broker_code) || p.broker_name || p.broker_code;
                    const bDispName = bName.length > 15 ? bName.slice(0, 14) + '…' : bName;

                    tableHtml += `
                        <tr style="cursor: default;">
                            <td class="col-rank">${idx + 1}</td>
                            <td title="${p.broker_code} - ${bName}">
                                <span class="brk-code info">${p.broker_code}</span>
                                <span class="brk-name">${bDispName}</span>
                            </td>
                            <td class="num"><strong>${posFormatted}</strong></td>
                            <td class="num muted">${floatStr}</td>
                            <td class="num">${avgStr}</td>
                            <td class="num ${netValClass}">${netValFormatted}</td>
                            <td class="num warn">${impliedStr}</td>
                        </tr>
                    `;
                });
            }

            tableHtml += `</tbody></table></div>`;
            bsViewContainer.innerHTML = tableHtml;
        }

        // Bandarmology Controls Event Listeners
        document.querySelectorAll('.bs-period-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const target = e.currentTarget as HTMLElement;
                const period = target.getAttribute('data-bs-period') as BsPeriod;
                if (!period) return;

                document.querySelectorAll('.bs-period-btn').forEach(b => b.classList.remove('active'));
                target.classList.add('active');
                currentBsPeriod = period;

                if (period === 'custom') {
                    if (bsCustomDateRow) bsCustomDateRow.style.display = 'flex';
                    if (bsDateFrom && !bsDateFrom.value) {
                        bsDateFrom.value = new Date(Date.now() - 30 * 86400000).toISOString().split('T')[0];
                    }
                    if (bsDateTo && !bsDateTo.value) {
                        bsDateTo.value = new Date().toISOString().split('T')[0];
                    }
                } else {
                    if (bsCustomDateRow) bsCustomDateRow.style.display = 'none';
                    loadBandarmologyForActiveSymbol();
                }
            });
        });

        bsDateApplyBtn?.addEventListener('click', () => {
            if (!bsDateFrom || !bsDateTo) return;
            const fromVal = bsDateFrom.value;
            const toVal = bsDateTo.value;
            if (!fromVal || !toVal) {
                showToast('Pilih tanggal mulai dan akhir');
                return;
            }
            if (fromVal > toVal) {
                showToast('Tanggal mulai tidak boleh melebihi tanggal akhir');
                return;
            }
            bsCustomStartDate = fromVal;
            bsCustomEndDate = toVal;
            currentBsPeriod = 'custom';
            loadBandarmologyForActiveSymbol();
        });

        document.querySelectorAll('.bs-view-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const target = e.currentTarget as HTMLElement;
                const view = target.getAttribute('data-bs-view') as BsView;
                if (!view) return;

                document.querySelectorAll('.bs-view-btn').forEach(b => b.classList.remove('active'));
                target.classList.add('active');
                currentBsView = view;

                if (view === 'inventory') {
                    if (bsSearchBoxWrap) bsSearchBoxWrap.style.display = 'inline-flex';
                } else {
                    if (bsSearchBoxWrap) bsSearchBoxWrap.style.display = 'none';
                }

                loadBandarmologyForActiveSymbol();
            });
        });

        bsSearchBoxWrap?.addEventListener('click', () => {
            bsBrokerSearchInput?.focus();
        });

        document.querySelectorAll('.bs-flow-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const target = e.currentTarget as HTMLElement;
                const flow = target.getAttribute('data-bs-flow') as BsFlow;
                if (!flow) return;

                document.querySelectorAll('.bs-flow-btn').forEach(b => b.classList.remove('active'));
                target.classList.add('active');
                currentBsFlow = flow;

                loadBandarmologyForActiveSymbol();
            });
        });

        bsBrokerSearchInput?.addEventListener('input', () => {
            bsSearchQuery = (bsBrokerSearchInput?.value || '').trim();
            if (currentBsView === 'inventory') {
                renderBrokerInventoryView();
            }
        });

        bsRefreshBtn?.addEventListener('click', () => {
            bsRefreshBtn.classList.add('spin');
            setTimeout(() => bsRefreshBtn.classList.remove('spin'), 800);
            loadBandarmologyForActiveSymbol(true);
            showToast('Memperbarui data Bandarmology...');
        });

