        function getCompanyProfile(symbol: string): string {
            const sym = symbol.toUpperCase().trim();
            if (KNOWN_COMPANY_PROFILES[sym]) {
                return KNOWN_COMPANY_PROFILES[sym];
            }
            const comp = stockNameMap.get(sym);
            if (comp) {
                return `PT ${comp} (kode saham: ${sym}), emiten tercatat di Bursa Efek Indonesia.`;
            }
            return `Emiten tercatat di Bursa Efek Indonesia (kode saham: ${sym}).`;
        }

        function updateAiActiveSymbol() {
            const tInput = document.getElementById('ticker-input') as HTMLInputElement;
            const sym = (tInput?.value || 'BBCA').toUpperCase();
            if (aiActiveSymLabel) aiActiveSymLabel.textContent = sym;
            const comp = stockNameMap.get(sym) || '';
            if (aiReportSubtitle) {
                aiReportSubtitle.textContent = comp ? `${comp.slice(0, 20)}...` : 'Google Gemini AI';
                aiReportSubtitle.title = comp ? `${sym} - ${comp}` : sym;
            }
        }

