            // 4. S&R Pivots
            const srMatch = output.match(/Daily:\s*R2\s*Rp?([0-9.,]+)\s*\|\s*R1\s*Rp?([0-9.,]+)\s*\|\s*P\s*Rp?([0-9.,]+)\s*\|\s*S1\s*Rp?([0-9.,]+)\s*\|\s*S2\s*Rp?([0-9.,]+)/);
            const R2 = srMatch ? srMatch[1] : '-';
            const R1 = srMatch ? srMatch[2] : '-';
            const P = srMatch ? srMatch[3] : '-';
            const S1 = srMatch ? srMatch[4] : '-';
            const S2 = srMatch ? srMatch[5] : '-';

            // 5. Bandarmologi & Broker Flow
            const buyersMatch = output.match(/Buyers:\s*([^\n]+)/);
