            const heavyS = heavySMatch ? heavySMatch[1].trim() : '-';

            const foreignNetMatch = output.match(/(\*\*Net (?:Jual|Beli)\*\*[^\n]+)/);
            const foreignFlow = foreignNetMatch ? foreignNetMatch[1].replace(/\*\*/g, '').trim() : (output.includes('Net Jual') ? 'Net Jual' : (output.includes('Net Beli') ? 'Net Beli' : '-'));
            const foreign5dMatch = output.match(/5-hari:\s*([^\n]+)/);
            const foreign5d = foreign5dMatch ? foreign5dMatch[1].trim() : '';

            // Historical Accumulators & Distributers from bundle.brokerAcc
