        // =========================================================================
        // TRADE HISTORY & JOURNAL (STOCKBIT REAL EXECUTION TRACKER & TV LONG POSITION)
        // =========================================================================
        let allPositionsData: TradePosition[] = [];
        let allOpenPositionsData: TradePosition[] = [];
        let allForexPositionsData: TradePosition[] = [];
        let forexSummaryData: any = null;
        let forexCashflowData: any = null;
