        function ensureWatchlistSymbolsLoaded() {
            if (currentWatchlistKey === 'forex') {
                userWatchlists.forex = cleanForexWatchlist(userWatchlists.forex || []);
            }
            const allWl = [...new Set([...(userWatchlists.portfolio || []), ...(userWatchlists.traded || []), ...(userWatchlists.forex || [])])];
            for (const symRaw of allWl) {
                const rawTrimmed = (symRaw || '').trim();
                if (!rawTrimmed) continue;
                const isGold = rawTrimmed.toUpperCase().replace(/[MC]$/i, '') === 'XAUUSD';
                const sym = isGold ? 'XAUUSDm' : rawTrimmed.toUpperCase();
                const symUpper = sym.toUpperCase();
                const scr = screenerMap.get(sym) || screenerMap.get(symUpper);
                if (!scr || scr.price === 0 || !scr.prev_close || scr.prev_close <= 0) {
                    fetch(`/${sym}_1d.json`).then(r => r.ok ? r.json() : fetch(`/${symUpper}_1d.json`).then(r2 => r2.ok ? r2.json() : null)).then(bars => {
                        if (bars && Array.isArray(bars) && bars.length > 0) {
                            dailyBarsCache.set(sym, bars);
                            dailyBarsCache.set(symUpper, bars);
                            const lastBar = bars[bars.length - 1];
                            const prevBar = bars.length >= 2 ? bars[bars.length - 2] : null;
                            const p = Number(lastBar.close || lastBar.price || 0);
                            const pc = Number(prevBar?.close || lastBar.prev_close || p);
                            const chg = p - pc;
                            const chgPct = pc > 0 ? (chg / pc) * 100 : 0;
                            let item = screenerMap.get(sym) || screenerMap.get(symUpper);
                            const compTitle = (typeof getCompanyTitle === 'function' ? getCompanyTitle(sym) : stockNameMap.get(symUpper)) || '';
                            if (!item) {
                                item = {
                                    symbol: sym,
                                    name: compTitle,
                                    price: p,
                                    prev_close: pc,
                                    change: chg,
                                    change_percentage: chgPct,
                                    value: Number(lastBar.value || 0),
                                    volume: Number(lastBar.volume || 0),
                                    frequency: Number(lastBar.frequency || 0),
                                    net_foreign: Number(lastBar.net_foreign || 0)
                                };
                                screenerMap.set(sym, item);
                                screenerMap.set(symUpper, item);
                                screenerData.push(item);
                            } else {
                                if (item.price === 0 && p > 0) item.price = p;
                                if ((!item.prev_close || item.prev_close <= 0) && pc > 0) item.prev_close = pc;
                                if (item.prev_close && item.prev_close > 0 && item.price > 0) {
                                    item.change = item.price - item.prev_close;
                                    item.change_percentage = (item.change / item.prev_close) * 100;
                                }
                                if (!item.name && compTitle) item.name = compTitle;
                                item.symbol = sym;
                                screenerMap.set(sym, item);
                                screenerMap.set(symUpper, item);
                            }
                            if (currentDrawerMode === 'watchlist') {
                                renderWatchlist();
                            }
                        }
                    }).catch(() => {});

                    const isFx = (typeof getInstrumentFormatInfo === 'function' && getInstrumentFormatInfo(sym, 1).isForex);
                    if (!isFx) {
                        fetchRealtimePrice(sym).then((pData: BatchPriceStockItem | null) => {
                            if (pData) {
                                processRealtimePriceAlert(pData);
                                if (currentDrawerMode === 'watchlist') {
                                    renderWatchlist();
                                }
                            }
                        }).catch(() => {});
                    }
                }
            }
        }

