        function addSymbolToActiveWatchlist() {
            if (!wlAddInput) return;
            const raw = wlAddInput.value.trim();
            if (!raw) return;
            const sym = currentWatchlistKey === 'forex' ? canonicalizeForexSymbol(raw) : raw.toUpperCase();

            if (!userWatchlists[currentWatchlistKey]) {
                userWatchlists[currentWatchlistKey] = [];
            }

            const wlName = currentWatchlistKey === 'portfolio' ? 'Portofolio' : (currentWatchlistKey === 'forex' ? 'Forex' : 'Traded');
            const alreadyExists = userWatchlists[currentWatchlistKey].some(s => {
                if (s.toUpperCase() === sym.toUpperCase()) return true;
                if (currentWatchlistKey === 'forex') {
                    return s.toUpperCase().replace(/[MC]$/i, '') === sym.toUpperCase().replace(/[MC]$/i, '');
                }
                return false;
            });
            if (alreadyExists) {
                showToast(`${sym} is already in ${wlName}`);
                return;
            }

            userWatchlists[currentWatchlistKey].push(sym);
            if (currentWatchlistKey === 'forex') {
                userWatchlists.forex = cleanForexWatchlist(userWatchlists.forex);
            }
            saveWatchlists();

            // Asynchronously resolve daily bars & realtime price so %Chg and Price display immediately
            if (!screenerMap.has(sym)) {
                fetch(`/${sym}_1d.json`).then(r => r.ok ? r.json() : null).then(bars => {
                    if (bars && Array.isArray(bars) && bars.length > 0) {
                        dailyBarsCache.set(sym, bars);
                        const lastBar = bars[bars.length - 1];
                        const prevBar = bars.length >= 2 ? bars[bars.length - 2] : null;
                        const p = Number(lastBar.close || lastBar.price || 0);
                        const pc = Number(prevBar?.close || lastBar.prev_close || p);
                        const chg = p - pc;
                        const chgPct = pc > 0 ? (chg / pc) * 100 : 0;
                        let item = screenerMap.get(sym);
                        if (!item) {
                            item = {
                                symbol: sym,
                                name: stockNameMap.get(sym) || '',
                                price: p,
                                prev_close: pc,
                                change: chg,
                                change_percentage: chgPct,
                                value: Number(lastBar.value || 0),
                                volume: Number(lastBar.volume || 0),
                                frequency: Number(lastBar.frequency || 0),
                                net_foreign: Number(lastBar.net_foreign || 0)
                            };
                            screenerMap.set(sym, item);
                            screenerData.push(item);
                            renderDrawerTable();
                        }
                    }
                }).catch(() => {});

                const isFx = (typeof getInstrumentFormatInfo === 'function' && getInstrumentFormatInfo(sym, 1).isForex);
                if (!isFx) {
                    fetchRealtimePrice(sym).then((pData: BatchPriceStockItem | null) => {
                        if (pData) {
                            processRealtimePriceAlert(pData);
                            renderDrawerTable();
                        }
                    }).catch(() => {});
                }
            }

            renderDrawerTable();
            wlAddInput.value = '';
            showToast(`Added ${sym} to ${wlName}`);
        }

