            function resampleDailyToWeekly(dailyBars: any[]): any[] {
                if (!dailyBars || dailyBars.length === 0) return [];
                const sorted = [...dailyBars].sort((a, b) => a.time - b.time);
                const groups: { [key: string]: { mondayTs: number; bars: any[] } } = {};

                for (const b of sorted) {
                    const d = new Date(b.time * 1000);
                    const day = d.getUTCDay(); // 0 is Sun, 1 is Mon, ... 6 is Sat
                    const diff = (day === 0 ? -6 : 1) - day;
                    const monday = new Date(d);
                    monday.setUTCDate(d.getUTCDate() + diff);
                    monday.setUTCHours(0, 0, 0, 0);
                    const mondayTs = Math.floor(monday.getTime() / 1000);
                    const key = monday.toISOString().slice(0, 10);
                    if (!groups[key]) groups[key] = { mondayTs, bars: [] };
                    groups[key].bars.push(b);
                }

                const res: any[] = [];
                let prevClose: number | null = null;

                for (const key of Object.keys(groups).sort()) {
                    const { mondayTs, bars } = groups[key];
                    const first = bars[0];
                    const last = bars[bars.length - 1];

                    let high = -Infinity;
                    let low = Infinity;
                    let vol = 0;
                    let val = 0;
                    let freq = 0;
                    let fBuy = 0;
                    let fSell = 0;
                    let netF = 0;

                    for (const b of bars) {
                        if (b.high > high) high = b.high;
                        if (b.low < low) low = b.low;
                        vol += b.volume || 0;
                        val += b.value || 0;
                        freq += b.frequency || 0;
                        fBuy += b.foreign_buy || 0;
                        fSell += b.foreign_sell || 0;
                        netF += b.net_foreign || 0;
                    }

                    const open = first.open;
                    const close = last.close;
                    const chg = prevClose !== null ? Number((close - prevClose).toFixed(2)) : Number((close - open).toFixed(2));
                    const pct = prevClose !== null && prevClose !== 0
                        ? Number(((close - prevClose) / prevClose * 100).toFixed(2))
                        : (open !== 0 ? Number(((close - open) / open * 100).toFixed(2)) : 0);

                    const avg = (vol > 0 && val > 0) ? Math.round(val / (vol * 100)) : Math.round((open + high + low + close) / 4);

                    res.push({
                        time: mondayTs,
                        open,
                        high,
                        low,
                        close,
                        volume: vol,
                        value: val,
                        average: avg,
                        frequency: freq,
                        change: chg,
                        change_percentage: pct,
                        foreign_buy: fBuy,
                        foreign_sell: fSell,
                        net_foreign: netF,
                        levels: []
                    });

                    prevClose = close;
                }

                return res;
            }

