                const channels = detectAutoChannels(currentChartData, currentActiveTf, isLogScale);
                currentChannels = channels;

                const visibleChannels = channels.filter(ch => {
                    if (autoChannelMode === 'intact' && ch.isBroken) return false;
                    if (ch.type === 'up') return channelUpVisible;
                    if (ch.type === 'down') return channelDownVisible;
                    return true;
                });

                nativeChannelPrimitive.setChannels(visibleChannels);
                if (footprintChannelPrimitive) footprintChannelPrimitive.setChannels(visibleChannels);
                renderIndicatorsLegend();
