            // Traffic Light Logic (Momentum with Percentage Change)
            const tlLight = document.getElementById('tl-light') as HTMLElement;
            const tlLabel = document.getElementById('tl-label') as HTMLElement;
            const tlPercent = document.getElementById('tl-percent') as HTMLElement;
            const tlPeriodInput = document.getElementById('tl-period') as HTMLInputElement;

            function updateIndicators() {
                recalculateAllIndicators();
            }

            function updateTrafficLight() {
                if (!currentChartData || currentChartData.length === 0) return;
                
                let period = parseInt(tlPeriodInput?.value || '20', 10);
                if (isNaN(period) || period < 1) period = 20;

                const currentBar = currentChartData[currentChartData.length - 1];
                if (!currentBar || typeof currentBar.close !== 'number') return;
                const currentPrice = currentBar.close;

                // Make sure we have enough data
                if (currentChartData.length < period + 1) {
                    if (tlLight) tlLight.className = 'tl-bulb side';
                    if (tlLabel) {
                        tlLabel.innerText = 'N/A';
                        tlLabel.style.color = '#888';
                    }
                    if (tlPercent) {
                        tlPercent.innerText = '--';
                        tlPercent.style.color = '#888';
                    }
                    return;
                }

                // Momentum: Current Price vs Price N periods ago
                const pastBar = currentChartData[currentChartData.length - 1 - period];
                if (!pastBar || typeof pastBar.close !== 'number') return;
                const pastPrice = pastBar.close;
                const threshold = getIdxTickSize(pastPrice);

                const diff = currentPrice - pastPrice;
                const pctChange = pastPrice !== 0 ? (diff / pastPrice) * 100 : 0;
                const sign = pctChange > 0 ? '+' : '';
                const pctStr = `${sign}${pctChange.toFixed(2)}%`;

                if (tlPercent) {
                    tlPercent.innerText = pctStr;
                }

                if (currentPrice > pastPrice + threshold) {
                    if (tlLight) tlLight.className = 'tl-bulb bull';
                    if (tlLabel) {
                        tlLabel.innerText = 'BULL';
                        tlLabel.style.color = '#26a69a';
                    }
                    if (tlPercent) tlPercent.style.color = '#26a69a';
                } else if (currentPrice < pastPrice - threshold) {
                    if (tlLight) tlLight.className = 'tl-bulb bear';
                    if (tlLabel) {
                        tlLabel.innerText = 'BEAR';
                        tlLabel.style.color = '#ef5350';
                    }
                    if (tlPercent) tlPercent.style.color = '#ef5350';
                } else {
                    if (tlLight) tlLight.className = 'tl-bulb side';
                    if (tlLabel) {
                        tlLabel.innerText = 'SIDE';
                        tlLabel.style.color = '#fbc02d';
                    }
                    if (tlPercent) tlPercent.style.color = '#fbc02d';
                }

                const tlContainer = document.getElementById('traffic-light-container');
                if (tlContainer) {
                    tlContainer.title = `Momentum (${period} bars): Close ${currentPrice} vs ${pastPrice} (${pctStr})`;
                }
            }

            tlPeriodInput?.addEventListener('change', () => {
                updateTrafficLight();
                updateIndicators();
            });
            tlPeriodInput?.addEventListener('keyup', (e) => {
                if (e.key === 'Enter') {
                    updateTrafficLight();
                    updateIndicators();
                }
            });

