            function getCompanyTitle(sym: string): string {
                const s = sym.toUpperCase().trim();
                const sBase = s.replace(/[MC]$/, '');
                if (IDX_INDEX_NAMES[s]) return IDX_INDEX_NAMES[s];
                if (FOREX_PAIR_NAMES[sBase]) return FOREX_PAIR_NAMES[sBase];
                if (stockNameMap.has(s)) return stockNameMap.get(s)!;
                if (IDX_COMPANY_NAMES[s]) return IDX_COMPANY_NAMES[s];
                return `PT ${s} Indonesia Tbk`;
            }

            // Crosshair Legend Logic (TradingView style Top-Left OHLC + Vol + Extra)
            function updateOhlcLegend(bar: any) {
                const ohlcRow = document.getElementById('ohlc-legend-row');
                if (!ohlcRow || !bar) return;

                const tInput = document.getElementById('ticker-input') as HTMLInputElement;
                const sym = (tInput?.value || 'KAQI').toUpperCase().trim();
                const tf = (typeof currentActiveTf !== 'undefined' && currentActiveTf) ? currentActiveTf.toUpperCase() : '1D';

                // Determine instrument formatting (Forex 4 decimals vs IDX 0 decimals vs Index 2 decimals)
                const formatInfo = getInstrumentFormatInfo(sym, bar.close, currentChartData);

                // Update Header Ticker & Title
                const headerTicker = document.getElementById('header-ticker');
                if (headerTicker) headerTicker.textContent = sym;

                const headerCompany = document.getElementById('header-company-name');
                if (headerCompany) headerCompany.textContent = getCompanyTitle(sym);

                const headerMeta = document.getElementById('header-market-meta');
                if (headerMeta) {
                    const marketLabel = formatInfo.isForex ? 'FOREX' : (formatInfo.isIndex ? 'INDEX' : 'IDX');
                    headerMeta.textContent = `· ${tf} · ${marketLabel}`;
                }

                const assetBadge = document.getElementById('chart-asset-badge');
                if (assetBadge) assetBadge.textContent = sym.charAt(0) || 'K';

                const sCfg = typeof currentChartSettings !== 'undefined' ? currentChartSettings : null;
                const precOverride = sCfg && sCfg.precision !== 'default' ? parseInt(sCfg.precision, 10) : null;
                const effectivePrec = precOverride !== null && !isNaN(precOverride) ? precOverride : formatInfo.precision;

                const fmtP = (val: number | null | undefined): string => {
                    if (val === null || val === undefined || isNaN(val)) return '-';
                    if (effectivePrec > 0) {
                        return Number(val).toFixed(effectivePrec);
                    }
                    return Math.round(Number(val)).toLocaleString('en-US');
                };

                // Determine Previous Close
                let prevClose: number | null = null;
                if (currentChartData && currentChartData.length > 0) {
                    const idx = currentChartData.findIndex((b: any) => b.time === bar.time);
                    if (idx > 0) {
                        prevClose = currentChartData[idx - 1].close;
                    }
                }
                if (prevClose === null && bar.change !== undefined) {
                    prevClose = bar.close - bar.change;
                }

                const O = fmtP(bar.open);
                const H = fmtP(bar.high);
                const L = fmtP(bar.low);
                const C = fmtP(bar.close);
                const upCol = sCfg ? sCfg.bodyUp : '#089981';
                const downCol = sCfg ? sCfg.bodyDown : '#f23645';
                const isBull = (sCfg && sCfg.colorPrevClose && prevClose !== null)
                    ? (bar.close >= prevClose)
                    : (bar.close >= bar.open);
                const color = isBull ? upCol : downCol;

                let totalVolume = 0;
                if (bar.volume !== undefined) {
                    totalVolume = bar.volume;
                } else if (bar.levels) {
                    totalVolume = bar.levels.reduce((acc: number, lvl: any) => acc + (lvl.bidVolume || 0) + (lvl.askVolume || 0), 0);
                }

                let prevHtml = '';
                let chgHtml = '';

                const rawChg = prevClose !== null ? (bar.close - prevClose) : (bar.change !== undefined ? bar.change : null);
                const pct = (prevClose !== null && prevClose !== 0)
                    ? ((bar.close - prevClose) / prevClose * 100)
                    : (bar.change_percentage !== undefined ? bar.change_percentage : null);

                const showOhlc = sCfg ? sCfg.showStatusOhlc : true;
                const showChg = sCfg ? sCfg.showStatusBarChange : true;
                const showVol = sCfg ? sCfg.showStatusVolume : true;

                if (showOhlc && prevClose !== null) {
                    prevHtml = `<span style="color: #787b86;">Prev</span> <span class="legend-val" style="color: var(--tv-text-main, #131722);">${fmtP(prevClose)}</span>`;
                }

                if (showChg && rawChg !== null && pct !== null) {
                    const chgColor = rawChg > 0 ? upCol : (rawChg < 0 ? downCol : '#787b86');
                    const chgSign = rawChg > 0 ? '+' : '';
                    const pctSign = pct > 0 ? '+' : '';
                    chgHtml = `<span style="color: #787b86;">Chg</span> <span class="legend-val" style="color: ${chgColor}">${chgSign}${fmtP(rawChg)} (${pctSign}${pct.toFixed(2)}%)</span>`;
                }

                const ohlcHtml = showOhlc ? `
                    <span style="color: #787b86;">O</span> <span class="legend-val" style="color: ${color}">${O}</span>
                    <span style="color: #787b86;">H</span> <span class="legend-val" style="color: ${color}">${H}</span>
                    <span style="color: #787b86;">L</span> <span class="legend-val" style="color: ${color}">${L}</span>
                    <span style="color: #787b86;">C</span> <span class="legend-val" style="color: ${color}">${C}</span>
                    ${prevHtml}
                ` : '';

                const volHtml = showVol ? `
                    <span style="color: #787b86;">Vol</span> <span class="legend-val" style="color: var(--tv-text-main, #131722);">${formatVolume(totalVolume)}</span>
                ` : '';

                ohlcRow.innerHTML = `${ohlcHtml}${chgHtml}${volHtml}`;
            }

            function updateLegendToLatest() {
                if (!currentChartData || currentChartData.length === 0) return;
                const lastBar = currentChartData[currentChartData.length - 1];
                updateOhlcLegend(lastBar);
                activeIndicators.forEach(ind => updateLegendRowValue(ind));

                if (volumeVisible) {
                    updateVolumePanePositions();
                }
                if (valuePaneVisible) {
                    updateValuePanePositions();
                }
            }

            function updateCrosshairIndicatorBadges(param: any) {
                const labelsContainer = document.getElementById('crosshair-indicator-labels');
                if (!labelsContainer) return;

                if (
                    param.point === undefined ||
                    !param.time ||
                    param.point.x < 0 ||
                    param.point.x > (chartContainer?.clientWidth || 0) ||
                    param.point.y < 0 ||
                    param.point.y > (chartContainer?.clientHeight || 0)
                ) {
                    labelsContainer.innerHTML = '';
                    return;
                }

                const x = param.point.x;
                const items: { y: number; text: string; color: string; id: string }[] = [];

                activeIndicators.forEach(ind => {
                    if (!ind.visible) return;
                    const isDailyOrHigher = currentActiveTf === '1d' || currentActiveTf === '1W' || currentActiveTf === '1M' || currentActiveTf === '1Y';
                    if (isDailyOrHigher && !ind.visDaily) return;
                    if (!isDailyOrHigher && !ind.visIntraday) return;

                    const sData = param.seriesData.get(ind.series) as { value?: number; time: Time } | undefined;
                    if (sData && typeof sData.value === 'number') {
                        const coordY = ind.series.priceToCoordinate(sData.value);
                        if (coordY !== null && !isNaN(coordY)) {
                            items.push({
                                y: coordY,
                                text: getIndicatorMarkerLabel(ind),
                                color: ind.color,
                                id: ind.id,
                            });
                        }
                    }
                });

                if (items.length === 0) {
                    labelsContainer.innerHTML = '';
                    return;
                }

                // Sort items vertically (top to bottom on screen)
                items.sort((a, b) => a.y - b.y);

                // Anti-overlap layout: if badges are within 18px of each other, alternate left/right
                const positionedBadges: { x: number; y: number; text: string; color: string; align: 'center' | 'left' | 'right' }[] = [];
                const containerWidth = chartContainer?.clientWidth || 800;

                for (let i = 0; i < items.length; i++) {
                    const item = items[i];
                    let align: 'center' | 'left' | 'right' = 'center';
                    let posX = x;

                    const prev = i > 0 ? items[i - 1] : null;
                    const next = i < items.length - 1 ? items[i + 1] : null;

                    const closeToPrev = prev && Math.abs(item.y - prev.y) < 18;
                    const closeToNext = next && Math.abs(next.y - item.y) < 18;

                    if (closeToPrev || closeToNext) {
                        if (i % 2 === 0) {
                            posX = x - 6;
                            align = 'right';
                        } else {
                            posX = x + 6;
                            align = 'left';
                        }
                    } else {
                        posX = x;
                        align = 'center';
                    }

                    // Bounds protection so badges don't spill off the sides
                    if (posX < 35) {
                        posX = Math.max(4, posX);
                        align = 'left';
                    } else if (posX > containerWidth - 45) {
                        posX = Math.min(containerWidth - 4, posX);
                        align = 'right';
                    }

                    positionedBadges.push({
                        x: posX,
                        y: item.y,
                        text: item.text,
                        color: item.color,
                        align,
                    });
                }

                labelsContainer.innerHTML = positionedBadges.map(b => {
                    let transform = 'translate(-50%, -50%)';
                    if (b.align === 'left') transform = 'translate(0, -50%)';
                    if (b.align === 'right') transform = 'translate(-100%, -50%)';

                    return `
                        <div class="crosshair-ind-badge" style="left: ${b.x}px; top: ${b.y}px; transform: ${transform}; color: ${b.color};">
                            ${b.text}
                        </div>
                    `;
                }).join('');
            }

            let pendingCrosshairParam: any = null;
            let crosshairRafId: number | null = null;

            chart.subscribeCrosshairMove(param => {
                pendingCrosshairParam = param;
                if (crosshairRafId !== null) return;
                crosshairRafId = requestAnimationFrame(() => {
                    crosshairRafId = null;
                    const p = pendingCrosshairParam;
                    if (!p) return;

                    updateCrosshairIndicatorBadges(p);

                    if (
                        p.point === undefined ||
                        !p.time ||
                        p.point.x < 0 ||
                        p.point.x > (chartContainer?.clientWidth || 0) ||
                        p.point.y < 0 ||
                        p.point.y > (chartContainer?.clientHeight || 0)
                    ) {
                        updateLegendToLatest();
                        updateVolumeLegendValues();
                        if (valuePaneVisible) updateValueLegendValues();
                        return;
                    }

                    const data = p.seriesData.get(nativeCandles) as CandlestickData<Time> | undefined;
                    if (!data || !('close' in data)) {
                        updateLegendToLatest();
                        updateVolumeLegendValues();
                        if (valuePaneVisible) updateValueLegendValues();
                        return;
                    }

                    const timeSec = typeof p.time === 'number' ? p.time : ((p.time as any)?.timestamp || 0);
                    const fullBar = chartDataMap.get(p.time) || data;
                    updateOhlcLegend(fullBar);

                    activeIndicators.forEach(ind => {
                        updateLegendRowValue(ind, timeSec);
                    });

                    if (volumeVisible) {
                        updateVolumeLegendValues(p.time);
                    }
                    if (valuePaneVisible) {
                        updateValueLegendValues(p.time);
                    }
                });
            });

            window.addEventListener('resize', () => {
                if (volumeVisible) updateVolumePanePositions();
                if (valuePaneVisible) updateValuePanePositions();
            });

            chartContainer?.addEventListener('mouseup', () => {
                if (volumeVisible) updateVolumePanePositions();
                if (valuePaneVisible) updateValuePanePositions();
            });

            chartContainer?.addEventListener('mouseleave', () => {
                if (crosshairRafId !== null) {
                    cancelAnimationFrame(crosshairRafId);
                    crosshairRafId = null;
                }
                pendingCrosshairParam = null;
                updateLegendToLatest();
                updateVolumeLegendValues();
                if (valuePaneVisible) updateValueLegendValues();
                const labelsContainer = document.getElementById('crosshair-indicator-labels');
                if (labelsContainer) labelsContainer.innerHTML = '';
            });

            // Top Header Action Buttons
            document.getElementById('screenshot-btn')?.addEventListener('click', () => {
                try {
                    const canvas = chart.takeScreenshot(true);
                    const link = document.createElement('a');
                    const tickerInput = document.getElementById('ticker-input') as HTMLInputElement;
                    const ticker = (tickerInput?.value || 'CHART').toUpperCase();
                    link.download = `${ticker}_${currentActiveTf}_${Date.now()}.png`;
                    link.href = canvas.toDataURL('image/png');
                    link.click();
                    showToast('Chart snapshot downloaded');
                } catch (e) {
                    console.error('Snapshot failed', e);
                    showToast('Snapshot capture failed');
                }
            });

            document.getElementById('fullscreen-btn')?.addEventListener('click', () => {
                if (!document.fullscreenElement) {
                    document.documentElement.requestFullscreen().catch(err => {
                        console.error(`Error attempting to enable fullscreen: ${err.message}`);
                    });
                } else {
                    if (document.exitFullscreen) {
                        document.exitFullscreen();
                    }
                }
            });

            // Zoom Controls (Wider / Narrower Candles)
            document.getElementById('zoom-in-btn')?.addEventListener('click', () => {
                const range = chart.timeScale().getVisibleLogicalRange();
                if (range) {
                    const count = range.to - range.from;
                    const newCount = Math.max(6, Math.floor(count * 0.7)); // Zoom in for wider candles
                    chart.timeScale().setVisibleLogicalRange({
                        from: range.to - newCount,
                        to: range.to
                    });
                }
            });

            document.getElementById('zoom-out-btn')?.addEventListener('click', () => {
                const range = chart.timeScale().getVisibleLogicalRange();
                if (range) {
                    const count = range.to - range.from;
                    const newCount = Math.min(300, Math.floor(count * 1.4)); // Zoom out for narrower candles
                    chart.timeScale().setVisibleLogicalRange({
                        from: range.to - newCount,
                        to: range.to
                    });
                }
            });

            document.getElementById('tv-main-menu-btn')?.addEventListener('click', () => showToast('TradingView Main Menu'));
            document.getElementById('tv-user-avatar-btn')?.addEventListener('click', () => showToast('TradingView User Profile & Menu'));
            document.getElementById('tv-templates-btn')?.addEventListener('click', () => showToast('Indicator Templates feature coming soon'));
            document.getElementById('tv-alert-btn')?.addEventListener('click', () => {
                const dockAlertBtn = document.getElementById('dock-alerts-btn');
                if (dockAlertBtn) dockAlertBtn.click();
                else showToast('Support & Ghost Alerts panel');
            });
            document.getElementById('tv-replay-btn')?.addEventListener('click', () => showToast('Bar Replay feature coming soon'));
            document.getElementById('tv-save-btn')?.addEventListener('click', () => showToast('Chart layout saved successfully'));
            document.getElementById('tv-quick-search-btn')?.addEventListener('click', () => {
                const tInput = document.getElementById('ticker-input') as HTMLInputElement;
                tInput?.focus();
                tInput?.select();
            });
            document.getElementById('undo-btn')?.addEventListener('click', () => showToast('Undo action'));
            document.getElementById('redo-btn')?.addEventListener('click', () => showToast('Redo action'));
            
