            function handleIncomingNormalizedTrade(trade: LiveTradeRecord) {
                // 1. Add to running trades tape drawer
                addTradeToRunningTape(trade);

                // 2. Ingest into screener and watchlist
                let item = screenerMap.get(trade.symbol);
                if (!item) {
                    let calcPrev = trade.price;
                    if (trade.change_percentage !== undefined && trade.change_percentage !== 0) {
                        calcPrev = Math.round(trade.price / (1 + (trade.change_percentage / 100)));
                    } else {
                        const bars = dailyBarsCache.get(trade.symbol);
                        if (bars && bars.length > 0) {
                            const lastBar = bars[bars.length - 1];
                            const todayDailyTs = getWibComponents().dailyTs;
                            if (lastBar.time === todayDailyTs && bars.length >= 2) {
                                calcPrev = bars[bars.length - 2].close;
                            } else if (lastBar.prev_close && lastBar.prev_close > 0) {
                                calcPrev = lastBar.prev_close;
                            } else {
                                calcPrev = lastBar.close;
                            }
                        }
                    }
                    item = {
                        symbol: trade.symbol,
                        price: trade.price,
                        prev_close: calcPrev,
                        change: trade.price - calcPrev,
                        change_percentage: trade.change_percentage !== undefined ? trade.change_percentage : (calcPrev > 0 ? ((trade.price - calcPrev) / calcPrev) * 100 : 0),
                        value: 0,
                        volume: 0,
                        frequency: 0,
                        net_foreign: 0,
                        time: trade.timeSec
                    };
                    screenerData.push(item);
                    screenerMap.set(trade.symbol, item);
                }

                const oldPrice = item.price;
                item.price = trade.price;
                if (trade.change_percentage !== undefined && trade.change_percentage !== 0) {
                    item.change_percentage = trade.change_percentage;
                    if (item.prev_close && item.prev_close > 0) {
                        item.change = item.price - item.prev_close;
                    }
                } else if (item.prev_close && item.prev_close > 0) {
                    item.change = item.price - item.prev_close;
                    item.change_percentage = (item.change / item.prev_close) * 100;
                }
                item.volume = (item.volume || 0) + trade.lot;
                item.value = (item.value || 0) + trade.value;
                item.frequency = (item.frequency || 0) + 1;
                item.time = trade.timeSec;

                dirtyScreenerSymbols.add(trade.symbol);
                scheduleScreenerUpdate();

                if (trade.price > oldPrice) {
                    lastTickDirection.set(trade.symbol, 'up');
                } else if (trade.price < oldPrice) {
                    lastTickDirection.set(trade.symbol, 'down');
                } else {
                    lastTickDirection.set(trade.symbol, trade.action === 'BUY' ? 'up' : 'down');
                }

                // 3. Accumulate today's provisional candle for ALL stocks in ihsg_list.csv
                let todayC = clientTodayCandles.get(trade.symbol);
                if (!todayC) {
                    todayC = {
                        symbol: trade.symbol,
                        time: trade.dailyTs,
                        open: trade.price,
                        high: trade.price,
                        low: trade.price,
                        close: trade.price,
                        volume: trade.lot,
                        value: trade.price * trade.lot * 100,
                        frequency: 1,
                        change: item.change || 0,
                        change_percentage: trade.change_percentage || 0
                    };
                    clientTodayCandles.set(trade.symbol, todayC);
                } else {
                    todayC.high = Math.max(todayC.high, trade.price);
                    todayC.low = Math.min(todayC.low, trade.price);
                    todayC.close = trade.price;
                    todayC.volume = (todayC.volume || 0) + trade.lot;
                    todayC.value = (todayC.value || 0) + (trade.price * trade.lot * 100);
                    todayC.frequency = (todayC.frequency || 0) + 1;
                    if (trade.change_percentage !== undefined) todayC.change_percentage = trade.change_percentage;
                    if (item.change !== undefined) todayC.change = item.change;
                }

                // 4. If matching active stock, ingest into active chart
                const tInput = document.getElementById('ticker-input') as HTMLInputElement;
                const activeTicker = (tInput?.value || '').toUpperCase();
                if (trade.symbol === activeTicker || isForexMatch(trade.symbol, activeTicker)) {
                    ingestTickIntoActiveChart({
                        symbol: trade.symbol,
                        price: trade.price,
                        lot: trade.lot,
                        action: trade.action,
                        time: trade.timeSec,
                        timeStr: trade.timeStr,
                        dailyTs: trade.dailyTs
                    });
                }

                // 5. Dual-Engine Alerts: Engine 1 (Running Trade Listener for First Touch ONLY)
                const alert = followThroughAlerts.get(trade.symbol);
                if (alert) {
                    // Strict Disconnect: If already touched today, immediately disconnect from live trade ticks!
                    if (!alert.isTouchedToday && !alert.firstTouchLog) {
                        let isTouching = false;
                        if (alert.primarySupport.isZone) {
                            const bot = alert.primarySupport.zoneBottom || 0;
                            const top = alert.primarySupport.zoneTop || 0;
                            isTouching = (trade.price >= bot && trade.price <= top);
                        } else {
                            isTouching = (trade.price === alert.primarySupport.price);
                        }

                        if (isTouching) {
                            // First Touch detected!
                            const todayStr = new Date().toISOString().split('T')[0];
                            const timeStr = trade.timeStr ? `${trade.timeStr} WIB` : new Date().toLocaleTimeString('id-ID', { hour12: false }) + ' WIB';
                            alert.isTouchedToday = true;
                            alert.status = 'testing';
                            alert.currentPrice = trade.price;
                            alert.changePercentage = trade.change_percentage !== undefined ? trade.change_percentage : alert.changePercentage;

                            const firstLog: AlertMovementLogEntry = {
                                time: timeStr,
                                price: trade.price,
                                changePercent: alert.changePercentage || 0,
                                status: 'testing',
                                label: alert.primarySupport.isZone ? '🎯 Testing Demand Zone' : '🎯 Testing Support Line',
                                distanceTicks: 0,
                                distancePercent: 0,
                                date: todayStr
                            };
                            alert.firstTouchLog = firstLog;
                            alert.currentAlertLog = { ...firstLog };
                            if (!alert.rawMovementLogs) alert.rawMovementLogs = [];
                            alert.rawMovementLogs.push({ ...firstLog });

                            // Dispatch First Touch Alert immediately to Discord & Telegram
                            dispatchFollowThroughAlert(alert, trade, 'testing');
                            showToast(`🎯 [FIRST TOUCH] ${trade.symbol} TOUCHED SUPPORT at Rp ${trade.price.toLocaleString('id-ID')}!`);

                            saveFollowThroughToStorage();
                            updateAlertTabCounts();
                            if (currentDrawerMode === 'alerts') {
                                renderAlertsUI();
                            }
                        }
                    }
                }
            }

            let pendingBackfillSymbol: string | null = null;

            function requestIntradayBackfill(symbol: string) {
                if (!symbol) return;
                const sym = symbol.trim().toUpperCase();
                if (liveSocket && liveSocket.readyState === WebSocket.OPEN) {
                    liveSocket.send(JSON.stringify({ action: 'get_intraday', symbol: sym }));
                    pendingBackfillSymbol = null;
                } else {
                    pendingBackfillSymbol = sym;
                }
            }

            function handleIntradaySnapshot(symbol: string, bars: any[], todayDailyBar?: any) {
                if (!symbol) return;
                const sym = symbol.toUpperCase().trim();
                const currentSymbol = getCurrentSymbol();
                if (sym !== currentSymbol && !isForexMatch(sym, currentSymbol)) return;

                // 1. Buffer incoming bridge data for today
                if (todayDailyBar) {
                    clientTodayCandles.set(sym, todayDailyBar);
                }
                if (Array.isArray(bars) && bars.length > 0) {
                    bridgeRecent1mBars.set(sym, bars);
                }

                // 2. If full historical daily data IS loaded for this ticker, update today's candle in cached1dData
                if ((cached1dLoadedTicker === sym || isForexMatch(cached1dLoadedTicker, sym)) && cached1dData && cached1dData.length > 0) {
                    const dBar = todayDailyBar || clientTodayCandles.get(sym);
                    if (dBar) {
                        mergeProvisionalCandleIntoDaily(cached1dData, dBar);
                    }
                }

                // 3. If full historical 1m data IS loaded for this ticker, merge bars into cached1mData
                if ((cached1mLoadedTicker === sym || isForexMatch(cached1mLoadedTicker, sym)) && cached1mData && cached1mData.length > 0 && Array.isArray(bars) && bars.length > 0) {
                    cached1mData = merge1mBarsWithBridge(cached1mData, bars);
                }

                // 4. Update the active chart view ONLY if the active dataset has actually been loaded from disk!
                const isDailyOrHigher = currentActiveTf === '1d' || currentActiveTf === '1W' || currentActiveTf === '1M' || currentActiveTf === '1Y';
                if (isDailyOrHigher) {
                    // Only re-render if cached1dData has the full historical dataset!
                    if ((cached1dLoadedTicker === sym || isForexMatch(cached1dLoadedTicker, sym)) && cached1dData && cached1dData.length > 0) {
                        let targetData = cached1dData;
                        if (currentActiveTf === '1W') targetData = resampleDailyToWeekly(cached1dData);
                        else if (currentActiveTf === '1M') targetData = resampleDailyToMonthly(cached1dData);
                        else if (currentActiveTf === '1Y') targetData = resampleDailyToYearly(cached1dData);
                        else if (currentActiveTf === '1d' && (cached1mLoadedTicker === sym || isForexMatch(cached1mLoadedTicker, sym)) && cached1mData.length > 0) {
                            targetData = merge1mFootprintIntoDaily(cached1dData, cached1mData);
                        }
                        try {
                            renderChartDataset(targetData, currentActiveTf);
                            updateLegendToLatest();
                            updateTrafficLight();
                            recalculateAllIndicators();
                            renderAutoSr();
                            renderGhostCandle();
                        } catch (err) {
                            console.error('[Intraday Backfill] Error applying daily backfill:', err);
                        }
                    }
                } else {
                    // Intraday (1m, 5m, 15m, 1h, 1S)
                    // Only re-render if cached1mData has the full historical dataset!
                    if ((cached1mLoadedTicker === sym || isForexMatch(cached1mLoadedTicker, sym)) && cached1mData && cached1mData.length > 0) {
                        let targetData: any[] = cached1mData;
                        if (currentActiveTf === '5m') targetData = resampleIntradayBars(cached1mData, 300);
                        else if (currentActiveTf === '15m') targetData = resampleIntradayBars(cached1mData, 900);
                        else if (currentActiveTf === '1h') targetData = resampleIntradayBars(cached1mData, 3600);
                        else if (currentActiveTf === '1S') targetData = resampleIntradayToSessionBars(cached1mData);
                        try {
                            setupAndRenderIntraday(targetData, currentActiveTf, true);
                            updateLegendToLatest();
                            updateTrafficLight();
                            recalculateAllIndicators();
                            renderAutoSr();
                            renderGhostCandle();
                        } catch (err) {
                            console.error('[Intraday Backfill] Error applying intraday backfill:', err);
                        }
                    }
                }
            }

